/* ---- src/app/03-project-preview-service-worker.js ---- */
function canUseProjectPreviewServiceWorker() {
  return Boolean(
    window.isSecureContext &&
    'serviceWorker' in navigator &&
    (location.protocol === 'http:' || location.protocol === 'https:')
  );
}

function markProjectPreviewDirty(path = null, { all = false } = {}) {
  if (all || !path) {
    projectPreviewNeedsFullSync = true;
    projectPreviewDirtyPaths.clear();
    return;
  }
  projectPreviewDirtyPaths.add(normalizeProjectPath(path));
}

function yieldToMainThread() {
  return new Promise(resolve => {
    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(() => resolve(), { timeout: 50 });
    } else {
      setTimeout(resolve, 0);
    }
  });
}

function withTimeout(promise, timeoutMs, fallbackValue = null) {
  return new Promise(resolve => {
    const timeoutId = setTimeout(() => resolve(fallbackValue), timeoutMs);
    Promise.resolve(promise)
      .then(value => {
        clearTimeout(timeoutId);
        resolve(value);
      })
      .catch(() => {
        clearTimeout(timeoutId);
        resolve(fallbackValue);
      });
  });
}

async function ensureProjectPreviewServiceWorker() {
  if (!canUseProjectPreviewServiceWorker()) return null;
  if (projectPreviewServiceWorker) return projectPreviewServiceWorker;

  if (!projectPreviewServiceWorkerPromise) {
    projectPreviewServiceWorkerPromise = navigator.serviceWorker.register(PROJECT_PREVIEW_SW_URL, { scope: './', updateViaCache: 'none' })
      .then(async registration => {
        registration.update?.().catch(() => {});
        const readyRegistration = await withTimeout(
          navigator.serviceWorker.ready,
          PROJECT_PREVIEW_SW_READY_TIMEOUT_MS,
          registration
        );
        const worker = readyRegistration.active || registration.active;
        if (!worker) return null;
        projectPreviewServiceWorker = worker;
        return worker;
      })
      .catch(err => {
        void err;
        projectPreviewServiceWorker = null;
        return null;
      });
  }

  return projectPreviewServiceWorkerPromise;
}

function postProjectPreviewMessage(message, transfer = []) {
  return new Promise((resolve, reject) => {
    const worker = projectPreviewServiceWorker;
    if (!worker) {
      reject(new Error('Service Worker no disponible'));
      return;
    }

    const channel = new MessageChannel();
    const timeoutId = setTimeout(() => {
      channel.port1.close();
      reject(new Error('Timeout sincronizando preview'));
    }, 2500);

    channel.port1.onmessage = event => {
      clearTimeout(timeoutId);
      channel.port1.close();
      const data = event.data || {};
      if (data.ok) resolve(data);
      else reject(new Error(data.error || 'Error sincronizando preview'));
    };

    worker.postMessage(message, [channel.port2, ...transfer]);
  });
}

async function collectProjectPreviewEntries(paths = null) {
  const selectedPaths = paths ? new Set(Array.from(paths).map(path => normalizeProjectPath(path))) : null;
  const entries = [];
  let processed = 0;

  const resolver = (canonicalPath) => {
    const cleanPath = normalizeProjectPath(canonicalPath);
    return cleanPath ? getProjectPreviewUrl(cleanPath) : null;
  };

  for (const file of files) {
    if (file.isFolder) continue;
    const cleanPath = normalizeProjectPath(file.name);
    if (selectedPaths && !selectedPaths.has(cleanPath)) continue;

    const ext = getFileExtension(cleanPath);
    const isHtml = ext === 'html' || ext === 'htm';
    const isCss = ext === 'css';
    const rawContent = file.isBinary ? null : getFileText(file);
    let content = null;
    if (!file.isBinary) {
      if (isHtml) {
        content = applyNonDraggableImageGuard(
          resolveVirtualPathsLazy(rawContent, cleanPath, resolver),
          { preventPreviewFocus: previewBlockFocusForCurrentRender }
        );
      } else if (isCss) {
        content = resolveCssUrlsLazy(rawContent, cleanPath, resolver);
      } else {
        content = rawContent;
      }
    }

    entries.push({
      path: cleanPath,
      mimeType: file.mimeType || getMimeTypeForFilename(cleanPath),
      isBinary: Boolean(file.isBinary),
      content,
      blob: file.isBinary ? getFileBlob(file) : null
    });

    processed += 1;
    if (processed % 80 === 0) {
      await yieldToMainThread();
    }
  }

  return entries;
}

function getProjectPreviewUrl(path = '') {
  const cleanPath = normalizeProjectPath(path || 'index.html');
  const encodedPath = cleanPath
    .split('/')
    .filter(Boolean)
    .map(segment => encodeURIComponent(segment))
    .join('/');
  return new URL(`${PROJECT_PREVIEW_PREFIX}/${projectPreviewSessionId}/${encodedPath}`, location.href).href;
}

function getProjectPreviewPathFromUrl(urlValue) {
  try {
    const url = new URL(urlValue, location.href);
    const marker = `/${PROJECT_PREVIEW_PREFIX}/${projectPreviewSessionId}/`;
    const markerIndex = url.pathname.indexOf(marker);
    if (markerIndex === -1) return '';

    const encodedPath = url.pathname.slice(markerIndex + marker.length);
    return normalizeProjectPath(decodeURIComponent(encodedPath));
  } catch {
    return '';
  }
}

function getPreviewIframeUrl() {
  if (!previewIframe) return '';
  try {
    return previewIframe.contentWindow?.location?.href || previewIframe.src || '';
  } catch {
    return previewIframe.src || '';
  }
}

function getCompactPreviewPath(path) {
  const cleanPath = normalizeProjectPath(path);
  if (!cleanPath) return '';
  const parts = cleanPath.split('/').filter(Boolean);
  return parts.length > 2 ? `.../${parts.slice(-2).join('/')}` : cleanPath;
}

function isKnownProjectPreviewPath(path) {
  return Boolean(findProjectFileByStaticRoute(path));
}

function syncProjectPreviewNavigationState() {
  if (!previewIframe) return false;

  const currentPath = getProjectPreviewPathFromUrl(getPreviewIframeUrl());
  if (!currentPath) return false;

  const previousMissingPath = projectPreviewMissingPath;
  projectPreviewCurrentPath = currentPath;

  if (!isKnownProjectPreviewPath(currentPath)) {
    projectPreviewMissingPath = currentPath;
    setPreviewStatus(`${PREVIEW_NOT_FOUND_LABEL}: ${getCompactPreviewPath(currentPath)}`, 'error');
  } else {
    projectPreviewMissingPath = '';
    const entryPath = normalizeProjectPath(getEntryFile()?.name || '');
    const label = currentPath.toLowerCase() === entryPath.toLowerCase()
      ? PREVIEW_READY_LABEL
      : `Viendo: ${getCompactPreviewPath(currentPath)}`;
    setPreviewStatus(label, 'ready');
  }

  if (previousMissingPath !== projectPreviewMissingPath && editorMode === 'split') {
    renderFileExplorer();
  }
  return true;
}

async function syncProjectPreviewSnapshot({ full = false } = {}) {
  try {
    const worker = await ensureProjectPreviewServiceWorker();
    if (!worker) return false;

    const activePaths = new Set(files.filter(file => !file.isFolder).map(file => normalizeProjectPath(file.name)));
    const nextSiteRoot = getProjectPreviewSiteRootPath();
    const removedPaths = [];
    for (const knownPath of projectPreviewKnownPaths) {
      if (!activePaths.has(knownPath)) {
        removedPaths.push(knownPath);
      }
    }

    const siteRootChanged = nextSiteRoot !== projectPreviewSiteRoot;
    const needsFull = full || siteRootChanged || projectPreviewNeedsFullSync || projectPreviewKnownPaths.size === 0;
    const dirtyPaths = needsFull
      ? activePaths
      : new Set(Array.from(projectPreviewDirtyPaths).filter(path => activePaths.has(path)));

    if (!needsFull && dirtyPaths.size === 0 && removedPaths.length === 0) {
      return true;
    }

    const entries = await collectProjectPreviewEntries(dirtyPaths);
    await postProjectPreviewMessage({
      type: 'html-viewer:set-project',
      sessionId: projectPreviewSessionId,
      version: projectPreviewVersion + 1,
      siteRoot: nextSiteRoot,
      full: needsFull,
      entries,
      removedPaths
    });

    projectPreviewVersion += 1;
    projectPreviewSiteRoot = nextSiteRoot;
    projectPreviewKnownPaths = activePaths;
    projectPreviewDirtyPaths.clear();
    projectPreviewNeedsFullSync = false;
    return true;
  } catch {
    projectPreviewServiceWorker = null;
    projectPreviewServiceWorkerPromise = null;
    projectPreviewNeedsFullSync = true;
    return false;
  }
}
;

/* ---- src/app/04-models-entry-utils.js ---- */
function normalizeFileRecord(file) {
  if (file.isFolder) {
    file.name = normalizeProjectPath(file.name, { folder: true });
    file.type = 'folder';
    file.mimeType = 'inode/directory';
    file.size = 0;
  } else {
    file.name = normalizeProjectPath(file.name);
    file.type = getFileExtension(file.name) || file.type || 'plaintext';
    file.mimeType = file.mimeType || getMimeTypeForFilename(file.name);
    file.isBinary = Boolean(file.isBinary) || (!isTextFilename(file.name) && Boolean(file.blob));
    if (!file.isBinary && typeof file.content !== 'string') {
      file.content = String(file.content || '');
    }
    if (typeof file.size !== 'number') {
      file.size = file.isBinary && file.blob ? file.blob.size : new Blob([file.content || '']).size;
    }
  }
  if (typeof file.order !== 'number') {
    file.order = nextFileOrder++;
  }
  return file;
}

function ensureParentFoldersForPath(path) {
  const parts = normalizeProjectPath(path).split('/').filter(Boolean);
  parts.pop();
  let currentPath = '';
  for (const part of parts) {
    currentPath += `${part}/`;
    if (!files.some(file => file.isFolder && file.name.toLowerCase() === currentPath.toLowerCase())) {
      files.push(createFolderRecord(currentPath));
    }
  }
}

function normalizeProjectFiles() {
  files.forEach(normalizeFileRecord);
  const existingFolderPaths = new Set(
    files
      .filter(file => file.isFolder)
      .map(file => normalizeProjectPath(file.name, { folder: true }).toLowerCase())
  );
  const foldersToAdd = [];

  files.forEach(file => {
    if (file.isFolder) return;
    const parts = normalizeProjectPath(file.name).split('/').filter(Boolean);
    parts.pop();

    let currentPath = '';
    for (const part of parts) {
      currentPath += `${part}/`;
      const lookupPath = currentPath.toLowerCase();
      if (!existingFolderPaths.has(lookupPath)) {
        existingFolderPaths.add(lookupPath);
        foldersToAdd.push(createFolderRecord(currentPath));
      }
    }
  });

  if (foldersToAdd.length > 0) {
    files.push(...foldersToAdd);
  }
  files.forEach(normalizeFileRecord);
  nextFileOrder = Math.max(1, ...files.map(file => file.order || 0)) + 1;
  if (typeof preloadFontDataUrls === 'function') {
    preloadFontDataUrls();
  }
}

function createModelForFile(file) {
  if (!monacoLoaded || !isEditableFile(file)) return null;
  const language = getLanguageFromFilename(file.name);
  const model = monaco.editor.createModel(file.content || '', language);
  fileModels[file.id] = model;
  model.onDidChangeContent(() => {
    file.content = model.getValue();
    file.size = new Blob([file.content]).size;
    markProjectPreviewDirty(file.name);
    updateEditorPlaceholder();
    if (!isRestoringHistory) {
      handleTextChange();
    }
    schedulePreviewUpdate({ force: false });
  });
  return model;
}

function disposeAllFileModels() {
  if (!monacoLoaded) return;
  for (const model of Object.values(fileModels)) {
    model.dispose();
  }
  for (const key in fileModels) {
    delete fileModels[key];
  }
}

function syncModelsForFiles() {
  if (!monacoLoaded) return;
  files.forEach(file => {
    if (isEditableFile(file) && openFileIds.includes(file.id) && !fileModels[file.id]) {
      createModelForFile(file);
    }
  });
}

function getUniquePath(desiredPath, currentId = null, { folder = false } = {}) {
  const cleanPath = normalizeProjectPath(desiredPath, { folder });
  if (!cleanPath) return cleanPath;
  const parentPath = getParentPath(cleanPath);
  const baseName = getBaseName(cleanPath);
  const dotIndex = folder ? -1 : baseName.lastIndexOf('.');
  const stem = dotIndex > 0 ? baseName.substring(0, dotIndex) : baseName;
  const ext = dotIndex > 0 ? baseName.substring(dotIndex) : '';
  let candidate = cleanPath;
  let counter = 2;

  while (files.some(file => file.id !== currentId && file.name.toLowerCase() === candidate.toLowerCase())) {
    candidate = normalizeProjectPath(`${parentPath}${stem}-${counter}${ext}`, { folder });
    counter++;
  }

  return candidate;
}

function shouldReadFileAsText(file) {
  return isTextFilename(file.name) || /^text\//i.test(file.type || '');
}

function isHtmlFile(file) {
  if (!file || file.isFolder) return false;
  const ext = getFileExtension(file.name);
  return ext === 'html' || ext === 'htm';
}

function getHtmlFiles() {
  return files
    .filter(isHtmlFile)
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
}

async function createRecordFromBrowserFile(file, targetPath = '') {
  const baseName = file.name || 'archivo';
  const desiredPath = joinProjectPath(targetPath, baseName);
  const uniquePath = getUniquePath(desiredPath);

  if (shouldReadFileAsText(file)) {
    return createTextFileRecord(uniquePath, await file.text(), {
      mimeType: file.type || getMimeTypeForFilename(uniquePath),
      size: file.size
    });
  }

  const blob = file.slice(0, file.size, file.type || getMimeTypeForFilename(uniquePath));
  return createBinaryFileRecord(uniquePath, blob, {
    mimeType: file.type || getMimeTypeForFilename(uniquePath),
    size: file.size
  });
}

function getProjectRootFolder() {
  if (files.length === 0) return t('default_folder_name') + '/';
  for (const file of files) {
    const parts = file.name.split('/');
    if (parts.length > 0 && parts[0]) {
      return parts[0] + '/';
    }
  }
  return t('default_folder_name') + '/';
}

function isProjectRootFolderPath(folderPath) {
  return normalizeProjectPath(folderPath, { folder: true }) === getProjectRootFolder();
}

function scoreHtmlFile(file, rootFolder) {
  if (!file || file.isFolder) return -999999;

  let score = 0;

  // 1. Filename matching
  const name = file.name || '';
  const parts = name.split('/');
  const baseName = parts[parts.length - 1] || '';
  const baseLower = baseName.toLowerCase();

  if (baseLower === 'index.html' || baseLower === 'index.htm') {
    score += 100;
  } else if (
    baseLower === 'main.html' || baseLower === 'main.htm' ||
    baseLower === 'app.html' || baseLower === 'app.htm' ||
    baseLower === 'home.html' || baseLower === 'home.htm'
  ) {
    score += 50;
  } else {
    score += 10;
  }

  // 2. Depth calculation relative to project root
  let relativePath = name;
  if (rootFolder && name.startsWith(rootFolder)) {
    relativePath = name.substring(rootFolder.length);
  }
  const relParts = relativePath.split('/').filter(Boolean);
  const depth = Math.max(0, relParts.length - 1);
  score -= depth * 15;

  // 3. Folder segment penalties and rewards
  for (let i = 0; i < relParts.length - 1; i++) {
    const segment = relParts[i].toLowerCase();

    // Ignored / Excluded folders
    if (
      segment === 'node_modules' || segment === 'vendor' || segment === 'bower_components' ||
      segment === 'test' || segment === 'tests' || segment === 'spec' ||
      segment === 'coverage' || segment === 'docs' || segment === 'temp' ||
      segment === 'tmp' || segment === 'cache' || segment === '__tests__'
    ) {
      score -= 200;
    }
    // Component/fragment folders
    else if (
      segment === 'components' || segment === 'templates' || segment === 'fragments' ||
      segment === 'partials' || segment === 'views' || segment === 'widgets'
    ) {
      score -= 100;
    }
    // Build output folders
    else if (
      segment === 'dist' || segment === 'build' || segment === 'out' || segment === 'target'
    ) {
      score -= 30;
    }
    // Source / Public folders
    else if (
      segment === 'src' || segment === 'public' || segment === 'app'
    ) {
      score += 15;
    }
  }

  // 4. Content analysis (if file has text content)
  const content = file.content;
  if (typeof content === 'string') {
    const contentLen = content.length;
    if (contentLen < 30) {
      score -= 30;
    } else {
      const contentLower = content.toLowerCase();

      // Page structure tags
      if (contentLower.includes('<!doctype html>')) score += 30;
      if (contentLower.includes('<html')) score += 20;
      if (contentLower.includes('<body')) score += 20;
      if (contentLower.includes('<head')) score += 10;

      // Scripts/Links
      if (contentLower.includes('<script')) score += 15;
      if (contentLower.includes('<link')) score += 15;

      // Framework mounts
      if (
        contentLower.includes('id="app"') ||
        contentLower.includes('id="root"') ||
        contentLower.includes('<router-view')
      ) {
        score += 15;
      }

      // Template indicators
      if (
        contentLower.includes('{{') ||
        contentLower.includes('{%') ||
        contentLower.includes('<%')
      ) {
        score -= 40;
      }
    }
  }

  return score;
}

function detectBestEntryFile(htmlFiles) {
  if (!htmlFiles || htmlFiles.length === 0) return null;
  const rootFolder = getProjectRootFolder();

  let bestFile = null;
  let maxScore = -Infinity;

  for (const file of htmlFiles) {
    const score = scoreHtmlFile(file, rootFolder);
    if (score > maxScore) {
      maxScore = score;
      bestFile = file;
    }
  }

  return bestFile;
}

function getEntryFile() {
  const selectedEntryFile = files.find(f => f.id === selectedEntryFileId && isHtmlFile(f));
  if (selectedEntryFile) {
    return selectedEntryFile;
  }

  const htmlFiles = getHtmlFiles();
  let entryFile = detectBestEntryFile(htmlFiles);
  if (!entryFile) {
    entryFile = files.find(f => !f.isFolder && isEditableFile(f));
  }
  if (!entryFile) {
    entryFile = files.find(f => !f.isFolder);
  }
  return entryFile || null;
}

function syncSelectedEntryFile() {
  const htmlFiles = getHtmlFiles();
  const selectedStillValid = htmlFiles.some(file => file.id === selectedEntryFileId);
  if (!selectedStillValid) {
    const preferred = detectBestEntryFile(htmlFiles);
    selectedEntryFileId = preferred ? preferred.id : '';
  }
  return htmlFiles;
}

function updateEntryHtmlSelector() {
  syncSelectedEntryFile();
}

function setSelectedEntryFile(fileId) {
  const file = files.find(item => item.id === fileId);
  if (!isHtmlFile(file)) return;

  if (pendingHtmlOpenClick) {
    clearTimeout(pendingHtmlOpenClick.timeoutId);
    pendingHtmlOpenClick = null;
  }
  selectedEntryFileId = file.id;
  projectPreviewCurrentPath = normalizeProjectPath(file.name);
  projectPreviewMissingPath = '';
  projectPreviewLastUrl = '';
  updateEntryHtmlSelector();
  renderFileExplorer();
  updatePreview();
}

function handleExplorerFileClick(file) {
  if (!isHtmlFile(file)) {
    openFile(file.id);
    return;
  }

  if (pendingHtmlOpenClick && pendingHtmlOpenClick.fileId === file.id) {
    clearTimeout(pendingHtmlOpenClick.timeoutId);
    pendingHtmlOpenClick = null;
    setSelectedEntryFile(file.id);
    return;
  }

  if (pendingHtmlOpenClick) {
    clearTimeout(pendingHtmlOpenClick.timeoutId);
    const previousFileId = pendingHtmlOpenClick.fileId;
    pendingHtmlOpenClick = null;
    openFile(previousFileId);
  }

  pendingHtmlOpenClick = {
    fileId: file.id,
    timeoutId: setTimeout(() => {
      pendingHtmlOpenClick = null;
      openFile(file.id);
    }, 220)
  };
}

function formatBytes(bytes = 0) {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let value = bytes;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }
  return `${value >= 10 || unitIndex === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unitIndex]}`;
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function isValidFileName(name) {
  if (!name || name.trim() === '') return false;
  return !/[\\/:*?"<>|]/.test(name);
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

normalizeProjectFiles();

// Helper to get language from filename
function getLanguageFromFilename(filename) {
  const ext = getFileExtension(filename);
  switch (ext) {
    case 'html':
    case 'htm':
      return 'html';
    case 'css':
      return 'css';
    case 'js':
    case 'jsx':
      return 'javascript';
    case 'ts':
    case 'tsx':
      return 'typescript';
    case 'json':
      return 'json';
    case 'md':
      return 'markdown';
    case 'txt':
      return 'plaintext';
    case 'xml':
    case 'svg':
      return 'xml';
    default:
      return 'plaintext';
  }
}

// Helper to get Lucide icon name from filename
function getIconForFilename(filename) {
  const ext = getFileExtension(filename);
  switch (ext) {
    case 'html':
    case 'htm':
      return 'code-2';
    case 'css':
      return 'palette';
    case 'js':
    case 'jsx':
    case 'ts':
    case 'tsx':
      return 'braces';
    case 'json':
      return 'file-json';
    case 'md':
    case 'txt':
    case 'xml':
      return 'file-text';
    case 'png':
    case 'jpg':
    case 'jpeg':
    case 'webp':
    case 'gif':
    case 'svg':
    case 'ico':
      return 'image';
    case 'woff':
    case 'woff2':
    case 'ttf':
      return 'type';
    case 'mp3':
      return 'music';
    case 'mp4':
    case 'webm':
      return 'film';
    default:
      return 'file-text';
  }
}
;

/* ---- src/app/05-reference-resolution.js ---- */
// Helper to split unified HTML into HTML, CSS, JS components
function splitUnifiedCode(unifiedHtml) {
  let css = '';
  let js = '';
  let html = unifiedHtml;

  // Extract <style> blocks
  const styleRegex = /<style[^>]*>([\s\S]*?)<\/style>/gi;
  let styleMatch;
  while ((styleMatch = styleRegex.exec(unifiedHtml)) !== null) {
    css += styleMatch[1].trim() + '\n\n';
  }
  html = html.replace(styleRegex, '');

  // Extract inline <script> blocks (only those without 'src' attribute)
  const scriptRegex = /<script\b[^>]*>([\s\S]*?)<\/script>/gi;
  let scriptMatch;
  while ((scriptMatch = scriptRegex.exec(unifiedHtml)) !== null) {
    const openTag = scriptMatch[0];
    if (!/src\s*=/i.test(openTag)) {
      js += scriptMatch[1].trim() + '\n\n';
      html = html.replace(scriptMatch[0], '');
    }
  }

  // Inject link and script tags to reference the separate files
  if (css.trim()) {
    const linkTag = '\n<link rel="stylesheet" href="styles.css">';
    // Only inject if not already present
    if (!/href\s*=\s*(['"])(?:\.\/|\/)?styles\.css\1/i.test(html)) {
      if (/<head[^>]*>/i.test(html)) {
        html = html.replace(/(<\/head>)/i, `${linkTag}\n$1`);
      } else if (/<html[^>]*>/i.test(html)) {
        html = html.replace(/(<html[^>]*>)/i, `$1\n<head>${linkTag}\n</head>`);
      } else {
        html = linkTag + '\n' + html;
      }
    }
  }

  if (js.trim()) {
    const scriptTag = '\n<script src="script.js"></script>';
    // Only inject if not already present
    if (!/src\s*=\s*(['"])(?:\.\/|\/)?script\.js\1/i.test(html)) {
      if (/(<\/body>)/i.test(html)) {
        html = html.replace(/(<\/body>)/i, `${scriptTag}\n$1`);
      } else if (/(<\/html>)/i.test(html)) {
        html = html.replace(/(<\/html>)/i, `${scriptTag}\n$1`);
      } else {
        html = html + '\n' + scriptTag;
      }
    }
  }

  return {
    html: html.trim(),
    css: css.trim(),
    js: js.trim()
  };
}

function replaceProjectWithSplitSource(unifiedHtml, { emptyAsSingleFile = false } = {}) {
  const rootFolder = getProjectRootFolder();
  if (emptyAsSingleFile && !String(unifiedHtml || '').trim()) {
    files = [
      createTextFileRecord(rootFolder + 'index.html', '', { id: '1' })
    ];
    openFileIds = ['1'];
  } else {
    const { html, css, js } = splitUnifiedCode(unifiedHtml);
    files = [
      createTextFileRecord(rootFolder + 'index.html', html, { id: '1' }),
      createTextFileRecord(rootFolder + 'styles.css', css, { id: '2' }),
      createTextFileRecord(rootFolder + 'script.js', js, { id: '3' })
    ];
    openFileIds = ['1', '2', '3'];
  }

  activeFileId = '1';
  selectedEntryFileId = '1';
  normalizeProjectFiles();
}

// Helper to resolve relative paths to canonical virtual file system paths
function resolveRelativePath(basePath, relativePath) {
  const normalizedRelativePath = normalizeReferencePathValue(relativePath);
  // If it's an absolute URL or data URL, return it as-is
  if (/^(https?:|data:|blob:|mailto:|tel:|#)/i.test(normalizedRelativePath)) {
    return null;
  }

  // Strip leading "./" if present
  let cleanRel = normalizedRelativePath;
  if (cleanRel.startsWith('./')) {
    cleanRel = cleanRel.substring(2);
  }

  // If it starts with "/", it is root-relative
  if (cleanRel.startsWith('/')) {
    return cleanRel.substring(1);
  }

  const baseParts = basePath.split('/').filter(Boolean);
  const relParts = cleanRel.split('/');

  for (const part of relParts) {
    if (part === '.' || part === '') {
      continue;
    } else if (part === '..') {
      baseParts.pop();
    } else {
      baseParts.push(part);
    }
  }

  return baseParts.join('/');
}

function getReferencePathCandidates(hostFilename, refPath) {
  const { path } = splitPathSuffix(refPath);
  const canonicalPath = resolveRelativePath(getDirectoryPath(hostFilename), path);
  if (!canonicalPath) return [];

  const candidates = [canonicalPath];
  if (path.startsWith('/')) {
    const siteRoot = getProjectPreviewSiteRootPath();
    if (siteRoot) {
      candidates.push(normalizeProjectPath(`${siteRoot}/${canonicalPath}`));
    }
  }

  return candidates.filter((candidate, index, arr) => candidate && arr.indexOf(candidate) === index);
}

function splitPathSuffix(refPath) {
  const suffixMatch = String(refPath).match(/([?#].*)$/);
  return {
    path: suffixMatch ? refPath.slice(0, suffixMatch.index) : refPath,
    suffix: suffixMatch ? suffixMatch[0] : ''
  };
}

function getDirectoryPath(filename) {
  const cleanName = normalizeProjectPath(filename);
  const lastSlashIndex = cleanName.lastIndexOf('/');
  return lastSlashIndex === -1 ? '' : cleanName.substring(0, lastSlashIndex);
}

function getCommonProjectRootPath() {
  const filePaths = files
    .filter(file => !file.isFolder)
    .map(file => normalizeProjectPath(file.name))
    .filter(Boolean);
  if (filePaths.length === 0) return '';
  if (filePaths.some(path => !path.includes('/'))) return '';

  const firstSegment = filePaths[0].split('/')[0];
  return filePaths.every(path => path.startsWith(`${firstSegment}/`)) ? firstSegment : '';
}

function getProjectPreviewSiteRootPath() {
  const entryFile = getEntryFile();
  if (!entryFile) return getCommonProjectRootPath();

  const entryPath = normalizeProjectPath(entryFile.name);
  const entryDir = getDirectoryPath(entryPath);
  const entryBase = getBaseName(entryPath).toLowerCase();
  if ((entryBase === 'index.html' || entryBase === 'index.htm') && entryDir) {
    return entryDir;
  }

  const commonRoot = getCommonProjectRootPath();
  if (commonRoot && entryPath.startsWith(`${commonRoot}/`)) {
    return commonRoot;
  }

  return '';
}

function getStaticRouteCandidates(path) {
  const cleanPath = normalizeProjectPath(path);
  const candidates = [];
  const add = candidate => {
    const normalized = normalizeProjectPath(candidate);
    if (normalized && !candidates.includes(normalized)) candidates.push(normalized);
  };

  if (!cleanPath) {
    add('index.html');
    add('index.htm');
    return candidates;
  }

  add(cleanPath);
  const lastSegment = cleanPath.split('/').pop() || '';
  const hasExtension = /\.[^/.]+$/.test(lastSegment);
  if (!hasExtension) {
    add(`${cleanPath}.html`);
    add(`${cleanPath}.htm`);
    add(`${cleanPath}/index.html`);
    add(`${cleanPath}/index.htm`);
  }
  if (cleanPath.endsWith('/')) {
    add(`${cleanPath}index.html`);
    add(`${cleanPath}index.htm`);
  }
  return candidates;
}

function findProjectFileByStaticRoute(path, { preferSiteRoot = false } = {}) {
  const cleanPath = normalizeProjectPath(path);
  const siteRoot = getProjectPreviewSiteRootPath();
  const scopedPath = siteRoot && cleanPath && !cleanPath.toLowerCase().startsWith(`${siteRoot.toLowerCase()}/`)
    ? normalizeProjectPath(`${siteRoot}/${cleanPath}`)
    : cleanPath;
  const scopes = preferSiteRoot ? [scopedPath, cleanPath] : [cleanPath, scopedPath];

  for (const scope of scopes.filter((scope, index, arr) => arr.indexOf(scope) === index)) {
    for (const candidate of getStaticRouteCandidates(scope)) {
      const file = files.find(item => !item.isFolder && normalizeProjectPath(item.name).toLowerCase() === candidate.toLowerCase());
      if (file) return file;
    }
  }
  return null;
}

function makeRelativePath(fromFilename, toPath) {
  const fromDirParts = getDirectoryPath(fromFilename).split('/').filter(Boolean);
  const toParts = normalizeProjectPath(toPath).split('/').filter(Boolean);

  while (fromDirParts.length && toParts.length && fromDirParts[0] === toParts[0]) {
    fromDirParts.shift();
    toParts.shift();
  }

  const relativeParts = [
    ...fromDirParts.map(() => '..'),
    ...toParts
  ];
  return relativeParts.length ? relativeParts.join('/') : getBaseName(toPath);
}

function resolveReferenceValue(refPath, fileMap, entryFilename) {
  const { suffix } = splitPathSuffix(refPath);
  for (const candidatePath of getReferencePathCandidates(entryFilename, refPath)) {
    if (fileMap[candidatePath]) {
      return `${fileMap[candidatePath]}${suffix}`;
    }
  }
  return null;
}

function resolveSrcset(value, fileMap, entryFilename) {
  return value.split(',').map(part => {
    const trimmed = part.trim();
    if (!trimmed) return part;
    const pieces = trimmed.split(/\s+/);
    const resolved = resolveReferenceValue(pieces[0], fileMap, entryFilename);
    if (!resolved) return part;
    pieces[0] = resolved;
    return pieces.join(' ');
  }).join(', ');
}

function rewriteCssImportReference(match, quote, refPath, resolved) {
  const safeQuote = quote || '"';
  return match.replace(refPath, resolved).replace(/@import\s+url\(\s*([^'")\s][^)]*)\)/i, `@import url(${safeQuote}$1${safeQuote})`);
}

function resolveCssUrls(content, fileMap, entryFilename) {
  let result = content.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi, (match, quote, refPath) => {
    const resolved = resolveReferenceValue(refPath.trim(), fileMap, entryFilename);
    if (!resolved) return match;
    const safeQuote = quote || '"';
    return `url(${safeQuote}${resolved}${safeQuote})`;
  });

  result = result.replace(/@import\s+(?:url\(\s*)?(['"]?)([^'")\s]+)\1\s*\)?/gi, (match, quote, refPath) => {
    const resolved = resolveReferenceValue(refPath.trim(), fileMap, entryFilename);
    if (!resolved) return match;
    return rewriteCssImportReference(match, quote, refPath, resolved);
  });

  return result;
}

function findFileByReference(hostFilename, refPath, allowedExtensions = null) {
  for (const candidatePath of getReferencePathCandidates(hostFilename, refPath)) {
    const file = files.find(item => !item.isFolder && item.name.toLowerCase() === candidatePath.toLowerCase());
    if (!file) continue;
    if (allowedExtensions && !allowedExtensions.has(getFileExtension(file.name))) continue;
    return file;
  }
  return null;
}

function injectPreviewGuardIntoHtml(htmlContent, guardStyle, guardScript) {
  let result = String(htmlContent || '');
  if (/<head\b[^>]*>/i.test(result)) {
    return result.replace(/<head\b[^>]*>/i, match => `${match}\n${guardStyle}\n${guardScript}`);
  }
  if (/<html\b[^>]*>/i.test(result)) {
    return result.replace(/<html\b[^>]*>/i, match => `${match}\n<head>\n${guardStyle}\n${guardScript}\n</head>`);
  }
  return `${guardStyle}\n${guardScript}\n${result}`;
}

function applyNonDraggableImageGuard(htmlContent, { preventPreviewFocus = false } = {}) {
  const guardAttribute = preventPreviewFocus ? 'data-html-viewer-preview-guard' : 'data-html-viewer-image-guard';
  const focusGuardStyle = preventPreviewFocus
    ? `html[data-html-viewer-embedded-preview] *,html[data-html-viewer-embedded-preview] *::before,html[data-html-viewer-embedded-preview] *::after{-webkit-user-select:none!important;user-select:none!important;}html[data-html-viewer-embedded-preview] input,html[data-html-viewer-embedded-preview] textarea,html[data-html-viewer-embedded-preview] [contenteditable],html[data-html-viewer-embedded-preview] [role="textbox"]{caret-color:transparent!important;}`
    : '';
  const fontSmoothingStyle = `html,body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility;background-color:#ffffff;}`;
  const guardStyle = `<style ${guardAttribute}>img{-webkit-user-drag:none;user-drag:none;user-select:none;}${fontSmoothingStyle}${focusGuardStyle}</style>`;
  const focusGuardScript = preventPreviewFocus ? `
  document.documentElement.setAttribute('data-html-viewer-embedded-preview', '');
  const isEditableTarget = target => {
    if (!target || !target.closest) return false;
    return Boolean(target.closest('input,textarea,select,[contenteditable],[role="textbox"],.monaco-editor'));
  };
  const releaseEditableFocus = target => {
    const editable = target && target.closest ? target.closest('input,textarea,select,[contenteditable],[role="textbox"],.monaco-editor') : null;
    const active = document.activeElement;
    if (active && active !== document.body && active !== document.documentElement && isEditableTarget(active)) {
      active.blur();
    } else if (editable && editable.blur) {
      editable.blur();
    }
  };
  document.querySelectorAll('[autofocus]').forEach(element => element.removeAttribute('autofocus'));
  const originalFocus = HTMLElement.prototype.focus;
  HTMLElement.prototype.focus = function(...args) {
    if (isEditableTarget(this)) return;
    return originalFocus.apply(this, args);
  };
  document.addEventListener('pointerdown', event => {
    if (isEditableTarget(event.target)) {
      event.preventDefault();
      releaseEditableFocus(event.target);
    }
  }, true);
  document.addEventListener('focusin', event => {
    if (isEditableTarget(event.target)) {
      releaseEditableFocus(event.target);
    }
  }, true);
  document.addEventListener('keydown', event => {
    if (isEditableTarget(document.activeElement)) {
      event.preventDefault();
      event.stopPropagation();
      releaseEditableFocus(document.activeElement);
    }
  }, true);` : '';
  const guardScript = `<script ${guardAttribute}>
(() => {
  const disableImageDrag = () => {
    document.querySelectorAll('img').forEach(image => {
      image.setAttribute('draggable', 'false');
    });
  };
${focusGuardScript}
  document.addEventListener('dragstart', event => {
    if (event.target && event.target.closest && event.target.closest('img')) {
      event.preventDefault();
    }
  }, true);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', disableImageDrag, { once: true });
  } else {
    disableImageDrag();
  }
})();
</script>`;

  let result = String(htmlContent || '');
  if (!result.includes(guardAttribute)) {
    result = injectPreviewGuardIntoHtml(result, guardStyle, guardScript);
  }
  return result;
}

function inlineCssImports(cssContent, hostFilename, dataUrlMap, seenFiles = new Set()) {
  return cssContent.replace(/@import\s+(?:url\(\s*)?(['"])([^'"]+)\1\s*\)?\s*([^;]*);?/gi, (match, quote, refPath, mediaQuery) => {
    const importedFile = findFileByReference(hostFilename, refPath, new Set(['css']));
    if (!importedFile || seenFiles.has(importedFile.name)) return match;

    const nextSeen = new Set(seenFiles);
    nextSeen.add(importedFile.name);
    let importedContent = getFileText(importedFile);
    importedContent = inlineCssImports(importedContent, importedFile.name, dataUrlMap, nextSeen);
    importedContent = resolveCssUrls(importedContent, dataUrlMap, importedFile.name);

    const media = String(mediaQuery || '').trim();
    if (media) {
      return `@media ${media} {\n${importedContent}\n}`;
    }
    return importedContent;
  });
}

// Helper to resolve relative paths in HTML content to Blob URLs
function resolveVirtualPaths(content, fileMap, entryFilename) {
  if (!entryFilename) entryFilename = 'index.html';

  let result = content.replace(/\b(href|src|action|poster)\s*=\s*(['"])([^'"]+)\2/gi, (match, attr, quote, refPath) => {
    const resolved = resolveReferenceValue(refPath, fileMap, entryFilename);
    if (resolved) {
      return `${attr}=${quote}${resolved}${quote}`;
    }
    return match;
  });

  result = result.replace(/\bsrcset\s*=\s*(['"])([^'"]+)\1/gi, (match, quote, value) => {
    return `srcset=${quote}${resolveSrcset(value, fileMap, entryFilename)}${quote}`;
  });

  // Resolve virtual URLs inside inline style="..." attributes
  result = result.replace(/\bstyle\s*=\s*(['"])([\s\S]*?)\1/gi, (match, quote, styleContent) => {
    return `style=${quote}${resolveCssUrls(styleContent, fileMap, entryFilename)}${quote}`;
  });

  return result.replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gi, (match, cssContent) => {
    return match.replace(cssContent, resolveCssUrls(cssContent, fileMap, entryFilename));
  });
}
;

/* ---- src/app/06-virtual-assets.js ---- */
// Map to store current virtual Blob URLs
const virtualBlobUrls = {};
// Cache to store details of previously created blob URLs
// Structure: file.name -> { url, rawContent, resolvedContent, sourceBlob }
const blobUrlCache = {};

function cleanupVirtualBlobUrlCache() {
  const activeFileNames = new Set(files.filter(f => !f.isFolder).map(f => f.name));

  for (const name in blobUrlCache) {
    if (!activeFileNames.has(name)) {
      URL.revokeObjectURL(blobUrlCache[name].url);
      delete blobUrlCache[name];
    }
  }

  for (const key in virtualBlobUrls) {
    if (!activeFileNames.has(key)) {
      delete virtualBlobUrls[key];
    }
  }
}

function findFileByCanonicalPath(canonicalPath) {
  const lookupPath = normalizeProjectPath(canonicalPath).toLowerCase();
  return files.find(item => !item.isFolder && item.name.toLowerCase() === lookupPath) || null;
}

function resolveReferenceValueLazy(refPath, hostFilename, resolver) {
  const { suffix } = splitPathSuffix(refPath);
  for (const candidatePath of getReferencePathCandidates(hostFilename, refPath)) {
    const resolved = resolver(candidatePath);
    if (resolved) return `${resolved}${suffix}`;
  }
  return null;
}

function resolveSrcsetLazy(value, hostFilename, resolver) {
  return value.split(',').map(part => {
    const trimmed = part.trim();
    if (!trimmed) return part;
    const pieces = trimmed.split(/\s+/);
    const resolved = resolveReferenceValueLazy(pieces[0], hostFilename, resolver);
    if (!resolved) return part;
    pieces[0] = resolved;
    return pieces.join(' ');
  }).join(', ');
}

function resolveCssUrlsLazy(content, hostFilename, resolver) {
  let result = content.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi, (match, quote, refPath) => {
    const resolved = resolveReferenceValueLazy(refPath.trim(), hostFilename, resolver);
    if (!resolved) return match;
    const safeQuote = quote || '"';
    return `url(${safeQuote}${resolved}${safeQuote})`;
  });

  result = result.replace(/@import\s+(?:url\(\s*)?(['"]?)([^'")\s]+)\1\s*\)?/gi, (match, quote, refPath) => {
    const resolved = resolveReferenceValueLazy(refPath.trim(), hostFilename, resolver);
    if (!resolved) return match;
    return rewriteCssImportReference(match, quote, refPath, resolved);
  });

  return result;
}

function resolveVirtualPathsLazy(content, entryFilename, resolver) {
  let result = content.replace(/\b(href|src|action|poster)\s*=\s*(['"])([^'"]+)\2/gi, (match, attr, quote, refPath) => {
    const resolved = resolveReferenceValueLazy(refPath, entryFilename, resolver);
    if (resolved) {
      return `${attr}=${quote}${resolved}${quote}`;
    }
    return match;
  });

  result = result.replace(/\bsrcset\s*=\s*(['"])([^'"]+)\1/gi, (match, quote, value) => {
    return `srcset=${quote}${resolveSrcsetLazy(value, entryFilename, resolver)}${quote}`;
  });

  result = result.replace(/\bstyle\s*=\s*(['"])([\s\S]*?)\1/gi, (match, quote, styleContent) => {
    return `style=${quote}${resolveCssUrlsLazy(styleContent, entryFilename, resolver)}${quote}`;
  });

  return result.replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gi, (match, cssContent) => {
    return match.replace(cssContent, resolveCssUrlsLazy(cssContent, entryFilename, resolver));
  });
}

function ensureVirtualBlobUrl(file, resolving = new Set()) {
  if (!file || file.isFolder) return null;

  const cached = blobUrlCache[file.name];
  if (file.isBinary) {
    const ext = getFileExtension(file.name);
    const isFont = ['woff', 'woff2', 'ttf', 'otf', 'eot'].includes(ext);
    if (isFont && file.dataUrl) {
      virtualBlobUrls[file.name] = file.dataUrl;
      return file.dataUrl;
    }
    const currentBlob = getFileBlob(file);
    if (cached && cached.sourceBlob === currentBlob) {
      virtualBlobUrls[file.name] = cached.url;
      return cached.url;
    }
    if (cached) URL.revokeObjectURL(cached.url);
    const newUrl = URL.createObjectURL(currentBlob);
    blobUrlCache[file.name] = { url: newUrl, sourceBlob: currentBlob, rawContent: null, resolvedContent: null };
    virtualBlobUrls[file.name] = newUrl;
    return newUrl;
  }

  const rawContent = getFileText(file);
  const ext = getFileExtension(file.name);

  if (resolving.has(file.name)) {
    if (cached) return cached.url;
    const cycleUrl = URL.createObjectURL(getFileBlob(file));
    blobUrlCache[file.name] = { url: cycleUrl, rawContent, resolvedContent: rawContent, sourceBlob: null };
    virtualBlobUrls[file.name] = cycleUrl;
    return cycleUrl;
  }

  resolving.add(file.name);
  const resolver = (canonicalPath) => {
    const referencedFile = findFileByCanonicalPath(canonicalPath);
    return ensureVirtualBlobUrl(referencedFile, resolving);
  };

  let resolvedContent = rawContent;
  if (ext === 'html' || ext === 'htm') {
    resolvedContent = resolveVirtualPathsLazy(rawContent, file.name, resolver);
  } else if (ext === 'css') {
    resolvedContent = resolveCssUrlsLazy(rawContent, file.name, resolver);
  }
  resolving.delete(file.name);

  if (cached && cached.rawContent === rawContent && cached.resolvedContent === resolvedContent) {
    virtualBlobUrls[file.name] = cached.url;
    return cached.url;
  }

  if (cached) URL.revokeObjectURL(cached.url);
  const newUrl = URL.createObjectURL(getFileBlob(file, resolvedContent));
  blobUrlCache[file.name] = { url: newUrl, rawContent, resolvedContent, sourceBlob: null };
  virtualBlobUrls[file.name] = newUrl;
  return newUrl;
}

// Generate Blob URLs for all virtual files
function generateBlobUrls() {
  // Identify all active file names (non-folders)
  const activeFileNames = new Set(files.filter(f => !f.isFolder).map(f => f.name));

  // Revoke and remove cache entries for files that no longer exist
  for (const name in blobUrlCache) {
    if (!activeFileNames.has(name)) {
      URL.revokeObjectURL(blobUrlCache[name].url);
      delete blobUrlCache[name];
    }
  }

  // Clear map of old keys
  for (const key in virtualBlobUrls) {
    if (!activeFileNames.has(key)) {
      delete virtualBlobUrls[key];
    }
  }

  // First pass: ensure every file has a base Blob URL in virtualBlobUrls.
  files.forEach(file => {
    if (file.isFolder) return;

    const cached = blobUrlCache[file.name];
    if (file.isBinary) {
      const ext = getFileExtension(file.name);
      const isFont = ['woff', 'woff2', 'ttf', 'otf', 'eot'].includes(ext);
      if (isFont && file.dataUrl) {
        virtualBlobUrls[file.name] = file.dataUrl;
      } else {
        const currentBlob = getFileBlob(file);
        if (cached && cached.sourceBlob === currentBlob) {
          virtualBlobUrls[file.name] = cached.url;
        } else {
          if (cached) URL.revokeObjectURL(cached.url);
          const newUrl = URL.createObjectURL(currentBlob);
          blobUrlCache[file.name] = { url: newUrl, sourceBlob: currentBlob, resolvedContent: null, rawContent: null };
          virtualBlobUrls[file.name] = newUrl;
        }
      }
    } else {
      const currentRawContent = getFileText(file);
      if (cached && cached.rawContent === currentRawContent) {
        virtualBlobUrls[file.name] = cached.url;
      } else {
        // We will generate the final URL in the second pass, but we need a baseline URL
        // in virtualBlobUrls for other files to resolve. We use the cached URL if available,
        // or a new temporary one if not cached.
        if (cached) {
          virtualBlobUrls[file.name] = cached.url;
        } else {
          const tempUrl = URL.createObjectURL(getFileBlob(file));
          blobUrlCache[file.name] = { url: tempUrl, rawContent: currentRawContent, resolvedContent: null, sourceBlob: null };
          virtualBlobUrls[file.name] = tempUrl;
        }
      }
    }
  });

  // Second pass: resolve references and recreate URLs for text files if their resolved content changed.
  files.forEach(file => {
    if (file.isFolder || file.isBinary) return;

    const ext = getFileExtension(file.name);
    const rawContent = getFileText(file);

    let resolvedContent;
    if (ext === 'html' || ext === 'htm') {
      resolvedContent = resolveVirtualPaths(rawContent, virtualBlobUrls, file.name);
    } else if (ext === 'css') {
      resolvedContent = resolveCssUrls(rawContent, virtualBlobUrls, file.name);
    } else {
      resolvedContent = rawContent;
    }

    const cached = blobUrlCache[file.name];
    if (cached && cached.resolvedContent === resolvedContent && cached.rawContent === rawContent) {
      virtualBlobUrls[file.name] = cached.url;
    } else {
      if (cached) {
        URL.revokeObjectURL(cached.url);
      }
      const newBlob = getFileBlob(file, resolvedContent);
      const newUrl = URL.createObjectURL(newBlob);
      blobUrlCache[file.name] = {
        url: newUrl,
        rawContent: rawContent,
        resolvedContent: resolvedContent,
        sourceBlob: null
      };
      virtualBlobUrls[file.name] = newUrl;
    }
  });
}

function createVirtualFileUrlSnapshot() {
  const fileMap = {};
  const urlsToRevoke = [];

  files.forEach(file => {
    if (file.isFolder) return;
    const ext = getFileExtension(file.name);
    const isFont = ['woff', 'woff2', 'ttf', 'otf', 'eot'].includes(ext);
    if (isFont && file.dataUrl) {
      fileMap[file.name] = file.dataUrl;
      return;
    }
    const url = URL.createObjectURL(getFileBlob(file));
    fileMap[file.name] = url;
    urlsToRevoke.push(url);
  });

  files.forEach(file => {
    if (file.isFolder || file.isBinary) return;
    const ext = getFileExtension(file.name);
    if (ext !== 'html' && ext !== 'htm' && ext !== 'css') return;

    const rawContent = getFileText(file);
    const resolvedContent = ext === 'css'
      ? resolveCssUrls(rawContent, fileMap, file.name)
      : resolveVirtualPaths(rawContent, fileMap, file.name);

    const rewrittenUrl = URL.createObjectURL(getFileBlob(file, resolvedContent));
    fileMap[file.name] = rewrittenUrl;
    urlsToRevoke.push(rewrittenUrl);
  });

  return { fileMap, urlsToRevoke };
}

function createFullPagePreviewSnapshot() {
  if (editorMode === 'unified') {
    return {
      code: applyNonDraggableImageGuard(getCurrentPreviewCode()),
      urlsToRevoke: []
    };
  }

  const entryFile = getEntryFile();
  if (!entryFile) {
    return {
      code: createEmptyProjectPreviewCode(),
      urlsToRevoke: []
    };
  }

  const previewCode = applyNonDraggableImageGuard(getCurrentPreviewCode());
  const previewUrlMap = { ...virtualBlobUrls };
  const { fileMap, urlsToRevoke } = createVirtualFileUrlSnapshot();
  let code = previewCode;

  Object.entries(previewUrlMap).forEach(([path, previewUrl]) => {
    const snapshotUrl = fileMap[path];
    if (!previewUrl || !snapshotUrl) return;
    code = code.split(previewUrl).join(snapshotUrl);
  });

  return { code, urlsToRevoke };
}

async function createVirtualFileDataUrlSnapshot() {
  const dataUrlMap = {};

  for (const file of files) {
    if (file.isFolder) continue;
    try {
      dataUrlMap[file.name] = await blobToDataUrl(getFileBlob(file));
    } catch {
      // Leave references untouched if a browser refuses to encode a file.
    }
  }

  for (const file of files) {
    if (file.isFolder || file.isBinary) continue;
    const ext = getFileExtension(file.name);
    if (ext !== 'html' && ext !== 'htm' && ext !== 'css') continue;

    const rawContent = getFileText(file);
    const resolvedContent = ext === 'css'
      ? resolveCssUrls(rawContent, dataUrlMap, file.name)
      : resolveVirtualPaths(rawContent, dataUrlMap, file.name);

    try {
      dataUrlMap[file.name] = await blobToDataUrl(getFileBlob(file, resolvedContent));
    } catch {
      // Keep the first-pass Data URL if the rewritten version cannot be encoded.
    }
  }

  return dataUrlMap;
}

function preloadFontDataUrls() {
  let changed = false;
  const promises = files.map(file => {
    if (file.isBinary && file.blob && !file.dataUrl) {
      const ext = getFileExtension(file.name);
      const isFont = ['woff', 'woff2', 'ttf', 'otf', 'eot'].includes(ext);
      if (isFont) {
        return blobToDataUrl(file.blob).then(url => {
          file.dataUrl = url;
          changed = true;
        }).catch(err => {
          console.error('Failed to convert font blob to Data URL:', err);
        });
      }
    }
    return null;
  }).filter(Boolean);

  if (promises.length > 0) {
    Promise.all(promises).then(() => {
      if (changed && typeof schedulePreviewUpdate === 'function') {
        schedulePreviewUpdate();
      }
    });
  }
}

// Initial run
preloadFontDataUrls();
;

/* ---- src/app/07-preview-editor.js ---- */
const previewNavigationObservedDocuments = new WeakSet();

// Helper to get the current code to be rendered in the preview
function getCurrentPreviewCode() {
  if (!editor) return '';
  
  const rawContent = monacoLoaded ? unifiedModel.getValue() : fallbackTextarea.value;
  
  if (editorMode === 'unified') {
    let entryFile = getEntryFile();
    if (entryFile && (cameFromSplitMode || files.length > 1)) {
      cleanupVirtualBlobUrlCache();
      for (const key in virtualBlobUrls) {
        delete virtualBlobUrls[key];
      }

      const resolver = (canonicalPath) => {
        const referencedFile = findFileByCanonicalPath(canonicalPath);
        return ensureVirtualBlobUrl(referencedFile, new Set([entryFile.name]));
      };

      // Resolve paths inside the editor HTML using entryFile name as context
      return resolveVirtualPathsLazy(rawContent, entryFile.name, resolver);
    }
    return rawContent;
  } else {
    // Find the main HTML file: index.html, or first HTML file, or first file
    let entryFile = getEntryFile();

    if (!entryFile) return createEmptyProjectPreviewCode();

    cleanupVirtualBlobUrlCache();
    for (const key in virtualBlobUrls) {
      delete virtualBlobUrls[key];
    }

    const rawContent = getFileText(entryFile);
    const resolver = (canonicalPath) => {
      const referencedFile = findFileByCanonicalPath(canonicalPath);
      return ensureVirtualBlobUrl(referencedFile, new Set([entryFile.name]));
    };

    // Resolve paths inside the entry HTML
    return resolveVirtualPathsLazy(rawContent, entryFile.name, resolver);
  }
}

if (previewIframe) {
  const initialPreviewCode = createEmptyProjectPreviewCode('');
  markPreviewHomeNavigationPending();
  previewIframe.srcdoc = initialPreviewCode;
  lastPreviewCode = initialPreviewCode;
  previewIframe.classList.add('is-empty');
  previewIframe.addEventListener('load', () => {
    clearTimeout(renderingTimeoutId);
    const isProjectPreview = syncProjectPreviewNavigationState();
    syncPreviewHomeNavigationState(isProjectPreview);
    bindPreviewNavigationObserver();
    if (!isProjectPreview) {
      setPreviewStatus(PREVIEW_READY_LABEL, 'ready');
    }
    restoreEditorFocusAfterPreviewLoad();
  });
}

function setPreviewAwayFromHome(isAway) {
  previewIsAwayFromHome = Boolean(isAway);
  const button = document.getElementById('btn-preview-home');
  if (!button) return;
  button.disabled = !previewIsAwayFromHome;
  button.setAttribute('aria-disabled', String(!previewIsAwayFromHome));
}

function markPreviewHomeNavigationPending() {
  previewHomeNavigationPending = true;
  setPreviewAwayFromHome(false);
}

function syncPreviewHomeNavigationState(isProjectPreview) {
  if (previewHomeNavigationPending) {
    previewHomeNavigationPending = false;
    setPreviewAwayFromHome(false);
    return;
  }

  if (isProjectPreview) {
    const entryPath = normalizeProjectPath(getEntryFile()?.name || '').toLowerCase();
    const currentPath = normalizeProjectPath(projectPreviewCurrentPath || '').toLowerCase();
    setPreviewAwayFromHome(Boolean(currentPath && currentPath !== entryPath));
    return;
  }

  // A second iframe load not initiated by the editor means the rendered page
  // followed a link, including links to origins whose URL the parent cannot read.
  setPreviewAwayFromHome(true);
}

function bindPreviewNavigationObserver() {
  try {
    const previewDocument = previewIframe?.contentDocument;
    if (!previewDocument || previewNavigationObservedDocuments.has(previewDocument)) return;
    previewNavigationObservedDocuments.add(previewDocument);
    previewDocument.addEventListener('click', (event) => {
      const link = event.target?.closest?.('a[href]');
      if (!link || link.target === '_blank' || link.hasAttribute('download')) return;
      const href = (link.getAttribute('href') || '').trim();
      if (!href || href.startsWith('#') || href.toLowerCase().startsWith('javascript:')) return;
      setPreviewAwayFromHome(true);
    }, true);
  } catch {
    // Cross-origin destinations cannot be inspected after navigation; the load
    // state fallback still keeps the home action available.
  }
}

function returnPreviewToHome() {
  if (!editor || !previewIframe) return;
  lastPreviewCode = '';
  projectPreviewLastUrl = '';
  projectPreviewCurrentPath = '';
  projectPreviewMissingPath = '';
  markPreviewHomeNavigationPending();
  updatePreview();
}

// Filename auto-sizing helper
function adjustFilenameWidth() {
  if (!filenameInput) return;
  const charCount = filenameInput.value.length || 1;
  filenameInput.style.width = `${charCount}ch`;
}

if (filenameInput) {
  filenameInput.addEventListener('input', adjustFilenameWidth);
  // Initial run
  adjustFilenameWidth();
}

function setPreviewStatus(label, state = 'idle') {
  void label;
  void state;
}

function getEmptyPreviewColors() {
  const isDark = document.documentElement.getAttribute('data-theme') !== 'light';
  return isDark
    ? { background: '#1e1e24', text: '#9ca3af' }
    : { background: '#ffffff', text: '#64748b' };
}

function createEmptyProjectPreviewCode(message = EMPTY_PROJECT_PREVIEW_MESSAGE) {
  const { background, text } = getEmptyPreviewColors();
  const safeMessage = String(message || '').replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[char]));

  return `<!doctype html>
<html data-html-viewer-empty-preview>
<head>
<meta charset="utf-8">
<style>
html,body{min-height:100%;margin:0;background:${background};color:${text};}
body{display:grid;place-items:center;font:15px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}
</style>
</head>
<body>${safeMessage ? `<div>${safeMessage}</div>` : ''}</body>
</html>`;
}

function isEmptyPreviewCode(rawCode) {
  return !rawCode || !rawCode.trim() || String(rawCode).includes('data-html-viewer-empty-preview');
}

function editorHasKeyboardFocus() {
  if (monacoLoaded && editor && typeof editor.hasTextFocus === 'function') {
    return editor.hasTextFocus();
  }
  return document.activeElement === fallbackTextarea;
}

function restoreEditorFocusAfterPreviewLoad() {
  if (!previewShouldRestoreEditorFocus) return;
  previewShouldRestoreEditorFocus = false;
  const restore = () => {
    if (!editor) return;
    if (monacoLoaded && typeof editor.focus === 'function') {
      editor.focus();
    } else if (fallbackTextarea) {
      fallbackTextarea.focus({ preventScroll: true });
    }
  };
  requestAnimationFrame(restore);
  setTimeout(restore, 80);
  setTimeout(restore, 220);
}

function allowPreviewFocusOnNextRender() {
  previewAllowFocusOnNextRender = true;
}

function getPreviewFocusPolicyForRender() {
  const hadEditorFocus = editorHasKeyboardFocus();
  const allowFocus = previewAllowFocusOnNextRender;
  previewAllowFocusOnNextRender = false;
  return {
    blockFocus: hadEditorFocus && !allowFocus,
    restoreFocus: hadEditorFocus
  };
}

function updateEditorPlaceholder() {
  if (!editorPlaceholder || !editor) return;
  if (!monacoLoaded && fallbackTextarea?.style.display === 'block') {
    scheduleFallbackEditorChromeSync();
    editorPlaceholder.classList.add('hidden');
    return;
  }

  if (editorMode === 'split' && !activeFileId) {
    editorPlaceholder.classList.remove('hidden');
    editorPlaceholder.textContent = t('placeholder_open_file');
    return;
  }

  if (editorMode === 'split') {
    const activeFile = files.find(f => f.id === activeFileId);
    if (activeFile && !isEditableFile(activeFile)) {
      editorPlaceholder.classList.add('hidden');
      return;
    }
  }

  const code = monacoLoaded ? editor.getValue() : fallbackTextarea.value;
  const hasCode = code.trim().length > 0;
  editorPlaceholder.classList.toggle('hidden', hasCode);

  if (!hasCode) {
    if (editorMode === 'unified') {
      editorPlaceholder.textContent = t('placeholder_html');
    } else {
      const file = files.find(f => f.id === activeFileId);
      if (file) {
        const ext = getFileExtension(file.name);
        if (ext === 'html' || ext === 'htm') editorPlaceholder.textContent = t('placeholder_html');
        else if (ext === 'css') editorPlaceholder.textContent = t('placeholder_css');
        else if (ext === 'js' || ext === 'jsx') editorPlaceholder.textContent = t('placeholder_js');
        else if (ext === 'json') editorPlaceholder.textContent = t('placeholder_json');
        else if (ext === 'md') editorPlaceholder.textContent = t('placeholder_md');
        else editorPlaceholder.textContent = t('placeholder_code');
      }
    }
  }
}

let previewDebounceTimeout = null;

function getPreviewDebounceMs(force = false) {
  if (force) return 0;
  if (editorMode === 'unified') return 0;

  const fileCount = files.filter(file => !file.isFolder).length;
  if (fileCount > 1200) return PROJECT_PREVIEW_DEBOUNCE_MAX_MS;
  if (fileCount > 350) return 420;
  if (fileCount > 80) return 240;
  return PROJECT_PREVIEW_DEBOUNCE_MIN_MS;
}

function schedulePreviewUpdate({ force = false } = {}) {
  if (previewFrameRequest) {
    cancelAnimationFrame(previewFrameRequest);
    previewFrameRequest = 0;
  }
  if (previewDebounceTimeout) {
    clearTimeout(previewDebounceTimeout);
    previewDebounceTimeout = null;
  }

  if (force) {
    renderPreviewNow();
    return;
  }

  previewDebounceTimeout = setTimeout(() => {
    previewDebounceTimeout = null;
    previewFrameRequest = requestAnimationFrame(() => {
      previewFrameRequest = 0;
      renderPreviewNow();
    });
  }, getPreviewDebounceMs(force));
}

function renderSrcdocPreviewNow(rawCode) {
  if (!editor || !previewIframe) return;
  const isEmpty = isEmptyPreviewCode(rawCode);
  previewIframe.classList.toggle('is-empty', isEmpty);

  const focusPolicy = getPreviewFocusPolicyForRender();
  previewBlockFocusForCurrentRender = focusPolicy.blockFocus;
  const previewCode = isEmpty ? createEmptyProjectPreviewCode('') : rawCode;
  const code = applyNonDraggableImageGuard(previewCode, { preventPreviewFocus: previewBlockFocusForCurrentRender });
  updateEditorPlaceholder();

  if (code === lastPreviewCode) {
    clearTimeout(renderingTimeoutId);
    setPreviewStatus(PREVIEW_IDLE_LABEL, 'idle');
    return;
  }

  lastPreviewCode = code;
  previewRenderId += 1;

  clearTimeout(renderingTimeoutId);
  renderingTimeoutId = setTimeout(() => {
    setPreviewStatus(PREVIEW_RENDERING_LABEL, 'rendering');
  }, 250);

  previewShouldRestoreEditorFocus = focusPolicy.restoreFocus;
  markPreviewHomeNavigationPending();
  previewIframe.removeAttribute('src');
  previewIframe.srcdoc = code;
}

async function renderProjectPreviewNow(renderId) {
  if (!editor || !previewIframe || renderId !== previewRenderId) return;

  const entryFile = getEntryFile();
  if (!entryFile) {
    renderSrcdocPreviewNow(createEmptyProjectPreviewCode());
    return;
  }

  if (!getFileText(entryFile).trim()) {
    renderSrcdocPreviewNow(createEmptyProjectPreviewCode(''));
    return;
  }

  previewIframe.classList.remove('is-empty');
  updateEditorPlaceholder();

  const focusPolicy = getPreviewFocusPolicyForRender();
  previewBlockFocusForCurrentRender = focusPolicy.blockFocus;
  if (projectPreviewLastBlockFocus !== previewBlockFocusForCurrentRender) {
    projectPreviewLastBlockFocus = previewBlockFocusForCurrentRender;
    markProjectPreviewDirty(null, { all: true });
  }
  const hasServiceWorkerPreview = await syncProjectPreviewSnapshot();
  if (renderId !== previewRenderId) return;

  if (!hasServiceWorkerPreview) {
    renderSrcdocPreviewNow(getCurrentPreviewCode());
    return;
  }

  const entryUrl = `${getProjectPreviewUrl(entryFile.name)}?v=${projectPreviewVersion}`;
  const renderSignature = `project:${entryFile.name}:${projectPreviewVersion}`;
  if (renderSignature === lastPreviewCode && entryUrl === projectPreviewLastUrl) {
    clearTimeout(renderingTimeoutId);
    setPreviewStatus(PREVIEW_IDLE_LABEL, 'idle');
    return;
  }

  lastPreviewCode = renderSignature;
  projectPreviewLastUrl = entryUrl;
  projectPreviewCurrentPath = normalizeProjectPath(entryFile.name);

  clearTimeout(renderingTimeoutId);
  renderingTimeoutId = setTimeout(() => {
    setPreviewStatus(PREVIEW_RENDERING_LABEL, 'rendering');
  }, 160);

  previewShouldRestoreEditorFocus = focusPolicy.restoreFocus;
  markPreviewHomeNavigationPending();
  previewIframe.removeAttribute('srcdoc');
  previewIframe.src = entryUrl;
}

function renderPreviewNow() {
  if (!editor || !previewIframe) return;
  previewRenderId += 1;
  const renderId = previewRenderId;

  if (editorMode === 'unified') {
    renderSrcdocPreviewNow(getCurrentPreviewCode());
    return;
  }

  renderProjectPreviewNow(renderId);
}

function getEditorLineHeight(fontSize = editorFontSize) {
  return Math.round(fontSize * 1.4);
}

function syncEditorTypographyVariables() {
  const editorContainer = document.getElementById('editor-container');
  if (!editorContainer) return;

  editorContainer.style.setProperty('--editor-font-size', `${editorFontSize}px`);
  editorContainer.style.setProperty('--editor-line-height', `${getEditorLineHeight()}px`);
}

function setEditorFontSize(fontSize) {
  const nextSize = Math.min(EDITOR_MAX_FONT_SIZE, Math.max(EDITOR_MIN_FONT_SIZE, fontSize));
  if (nextSize === editorFontSize) return;

  editorFontSize = nextSize;
  syncEditorTypographyVariables();

  if (monacoLoaded && editor && typeof editor.updateOptions === 'function') {
    editor.updateOptions({
      fontSize: editorFontSize,
      lineHeight: getEditorLineHeight()
    });
    syncEditorZoomGutter();
  } else {
    scheduleFallbackEditorChromeSync();
  }
}

function syncEditorZoomGutter() {
  if (!monacoLoaded || !editor || typeof editor.getLayoutInfo !== 'function') return;

  const isMobile = window.innerWidth <= 768;
  const layoutInfo = editor.getLayoutInfo();
  const options = editor.getRawOptions?.();
  const currentDecorationsWidth = Number(options?.lineDecorationsWidth) || 0;
  const fixedGutterWidth = layoutInfo.contentLeft - currentDecorationsWidth;
  const nextDecorationsWidth = Math.max(0, Math.round(EDITOR_CONTENT_LEFT - fixedGutterWidth));

  editor.updateOptions({
    lineNumbersMinChars: isMobile ? 2 : 3,
    folding: !isMobile
  });

  if (nextDecorationsWidth !== currentDecorationsWidth) {
    editor.updateOptions({ lineDecorationsWidth: nextDecorationsWidth });
  }
}

function initEditorWheelZoom() {
  const editorContainer = document.getElementById('editor-container');
  if (!editorContainer) return;

  const zoomIndicator = document.createElement('div');
  zoomIndicator.className = 'editor-zoom-indicator';
  zoomIndicator.setAttribute('role', 'status');
  zoomIndicator.setAttribute('aria-live', 'polite');
  editorContainer.appendChild(zoomIndicator);
  let hideZoomIndicatorTimeout = null;

  const showZoomIndicator = () => {
    const percentage = Math.round((editorFontSize / EDITOR_DEFAULT_FONT_SIZE) * 100);
    zoomIndicator.textContent = `${percentage}%`;
    zoomIndicator.classList.add('visible');
    clearTimeout(hideZoomIndicatorTimeout);
    hideZoomIndicatorTimeout = setTimeout(() => {
      zoomIndicator.classList.remove('visible');
    }, 900);
  };

  syncEditorTypographyVariables();
  editorContainer.addEventListener('wheel', (event) => {
    if (!event.ctrlKey || event.deltaY === 0) return;

    event.preventDefault();
    event.stopPropagation();
    setEditorFontSize(editorFontSize + (event.deltaY < 0 ? 1 : -1));
    showZoomIndicator();
  }, { passive: false, capture: true });
}

initEditorWheelZoom();

let fallbackEditorChromeFrame = 0;

function syncFallbackEditorChrome() {
  fallbackEditorChromeFrame = 0;
  if (monacoLoaded || !fallbackTextarea || !fallbackLineNumbers || !fallbackCurrentLine) return;

  const value = fallbackTextarea.value || '';
  const lineCount = Math.max(1, value.split('\n').length);
  const currentLine = value.slice(0, fallbackTextarea.selectionStart || 0).split('\n').length;
  const lineHeight = getEditorLineHeight();
  const scrollTop = fallbackTextarea.scrollTop || 0;
  const firstVisibleLine = Math.max(0, Math.floor(scrollTop / lineHeight) - 1);
  const visibleLineCount = Math.ceil((fallbackTextarea.clientHeight || lineHeight) / lineHeight) + 3;
  const lastVisibleLine = Math.min(lineCount, firstVisibleLine + visibleLineCount);

  fallbackLineNumbers.textContent = Array.from(
    { length: lastVisibleLine - firstVisibleLine },
    (_, index) => firstVisibleLine + index + 1
  ).join('\n');
  fallbackLineNumbers.style.transform = `translateY(${(firstVisibleLine * lineHeight) - scrollTop}px)`;
  fallbackCurrentLine.style.transform = `translateY(${((currentLine - 1) * lineHeight) - scrollTop}px)`;
}

function scheduleFallbackEditorChromeSync() {
  if (monacoLoaded || fallbackEditorChromeFrame) return;
  fallbackEditorChromeFrame = requestAnimationFrame(syncFallbackEditorChrome);
}

let fallbackTouchScrollInitialized = false;
function isMobileKeyboardLikelyOpen() {
  const viewport = window.visualViewport;
  return Boolean(viewport && window.innerHeight - viewport.height > 140);
}

function initFallbackTouchScroll() {
  if (fallbackTouchScrollInitialized || !fallbackTextarea) return;
  fallbackTouchScrollInitialized = true;
  let gesture = null;

  fallbackTextarea.addEventListener('touchstart', (event) => {
    if (window.innerWidth > COMPACT_LAYOUT_MAX_WIDTH || event.touches.length !== 1) return;
    if (document.activeElement === fallbackTextarea && isMobileKeyboardLikelyOpen()) return;
    const touch = event.touches[0];
    gesture = {
      startX: touch.clientX,
      startY: touch.clientY,
      lastX: touch.clientX,
      lastY: touch.clientY,
      scrollLeft: fallbackTextarea.scrollLeft,
      scrollTop: fallbackTextarea.scrollTop,
      moved: false
    };
    event.preventDefault();
  }, { passive: false, capture: true });

  fallbackTextarea.addEventListener('touchmove', (event) => {
    if (!gesture || event.touches.length !== 1) return;
    const touch = event.touches[0];
    gesture.lastX = touch.clientX;
    gesture.lastY = touch.clientY;
    if (Math.hypot(touch.clientX - gesture.startX, touch.clientY - gesture.startY) > 7) {
      gesture.moved = true;
    }
    fallbackTextarea.scrollLeft = gesture.scrollLeft + gesture.startX - touch.clientX;
    fallbackTextarea.scrollTop = gesture.scrollTop + gesture.startY - touch.clientY;
    scheduleFallbackEditorChromeSync();
    event.preventDefault();
  }, { passive: false, capture: true });

  fallbackTextarea.addEventListener('touchend', (event) => {
    if (!gesture) return;
    const shouldFocus = !gesture.moved;
    gesture = null;
    event.preventDefault();
    if (shouldFocus) fallbackTextarea.focus({ preventScroll: true });
  }, { passive: false, capture: true });

  fallbackTextarea.addEventListener('touchcancel', () => {
    gesture = null;
  }, { passive: true, capture: true });
}

let monacoTouchScrollNode = null;
function initMonacoTouchScroll() {
  const editorNode = editor?.getDomNode?.();
  if (!editorNode || monacoTouchScrollNode === editorNode) return;
  monacoTouchScrollNode = editorNode;
  let gesture = null;

  editorNode.addEventListener('touchstart', (event) => {
    if (window.innerWidth > COMPACT_LAYOUT_MAX_WIDTH || event.touches.length !== 1) return;
    if (editor.hasTextFocus?.() && isMobileKeyboardLikelyOpen()) return;
    const touch = event.touches[0];
    gesture = {
      startX: touch.clientX,
      startY: touch.clientY,
      lastX: touch.clientX,
      lastY: touch.clientY,
      scrollLeft: editor.getScrollLeft(),
      scrollTop: editor.getScrollTop(),
      moved: false
    };
    event.preventDefault();
  }, { passive: false, capture: true });

  editorNode.addEventListener('touchmove', (event) => {
    if (!gesture || event.touches.length !== 1) return;
    const touch = event.touches[0];
    gesture.lastX = touch.clientX;
    gesture.lastY = touch.clientY;
    if (Math.hypot(touch.clientX - gesture.startX, touch.clientY - gesture.startY) > 7) {
      gesture.moved = true;
    }
    editor.setScrollLeft(gesture.scrollLeft + gesture.startX - touch.clientX);
    editor.setScrollTop(gesture.scrollTop + gesture.startY - touch.clientY);
    event.preventDefault();
  }, { passive: false, capture: true });

  editorNode.addEventListener('touchend', (event) => {
    if (!gesture) return;
    const completedGesture = gesture;
    gesture = null;
    event.preventDefault();
    if (completedGesture.moved) return;

    const target = editor.getTargetAtClientPoint?.(completedGesture.lastX, completedGesture.lastY);
    if (target?.position) editor.setPosition(target.position);
    editor.focus();
  }, { passive: false, capture: true });

  editorNode.addEventListener('touchcancel', () => {
    gesture = null;
  }, { passive: true, capture: true });
}

// Fallback editor implementation if CDN fails or runs offline
function initFallbackEditor(showToastFlag = false) {
  if (monacoLoaded) return;
  fallbackTextarea.style.display = 'block';
  fallbackTextarea.value = INITIAL_EDITOR_CODE;
  fallbackTextarea.placeholder = EDITOR_PLACEHOLDER_TEXT;
  initFallbackTouchScroll();
  scheduleFallbackEditorChromeSync();

  fallbackTextarea.addEventListener('input', () => {
    if (!isRestoringHistory) {
      handleTextChange();
    }
    saveFallbackTabContent();
    schedulePreviewUpdate({ force: false });
    scheduleFallbackEditorChromeSync();
  });

  ['click', 'keyup', 'select', 'scroll'].forEach(eventName => {
    fallbackTextarea.addEventListener(eventName, scheduleFallbackEditorChromeSync, { passive: true });
  });

  fallbackTextarea.addEventListener('paste', () => {
    setTimeout(() => {
      allowPreviewFocusOnNextRender();
      saveFallbackTabContent();
      schedulePreviewUpdate({ force: true });
    }, 0);
  });

  editor = {
    getValue: () => {
      if (editorMode === 'unified') return fallbackTextarea.value;
      else {
        saveFallbackTabContent();
        let entryFile = getEntryFile();
        if (!entryFile) return '';
        generateBlobUrls();
        return resolveVirtualPaths(getFileText(entryFile), virtualBlobUrls, entryFile.name);
      }
    },
    setValue: (val) => {
      if (editorMode === 'unified') {
        cameFromSplitMode = false;
        const rootFolder = getProjectRootFolder();
        files = [
          createTextFileRecord(rootFolder + 'index.html', val, { id: '1' })
        ];
        openFileIds = ['1'];
        selectedEntryFileId = '1';
        fallbackTextarea.value = val;
      } else {
        replaceProjectWithSplitSource(val, { emptyAsSingleFile: true });
        if (val === '') {
          fallbackTextarea.value = '';
        } else {
          fallbackTextarea.value = getFileText(files.find(file => file.id === '1'));
        }
        renderActiveFileSummary();
        renderFileExplorer();
      }
      updateEditorPlaceholder();
      updatePreview();
    },
    layout: () => {},
    onDidChangeModelContent: () => {} // dummy
  };

  updateEditorPlaceholder();
  updatePreview();
  if (window.innerWidth > COMPACT_LAYOUT_MAX_WIDTH) {
    fallbackTextarea.focus();
  }
  if (showToastFlag) {
    showToast(t('toast_offline_mode'), 'info');
  }
}

// Initialize the fallback editor immediately to show content and allow editing without blocking
initFallbackEditor(false);

let monacoLoadPromise = null;
let monacoLoadFailureToastShown = false;

// Upgrade the instant fallback editor to the locally hosted Monaco build.
// The promise is shared so interaction, first-paint warmup and retries cannot
// start competing AMD loads.
function upgradeToMonaco() {
  if (monacoLoaded) return Promise.resolve(true);
  if (monacoLoadPromise) return monacoLoadPromise;

  const loadScript = (src) => new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.dataset.monacoLoader = 'true';

    let settled = false;
    const finish = (error = null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      s.onload = null;
      s.onerror = null;
      if (error) {
        s.remove();
        reject(error);
      } else {
        resolve();
      }
    };
    const timeoutId = setTimeout(() => {
      finish(new Error(`Monaco loader timed out after ${MONACO_LOAD_TIMEOUT_MS} ms`));
    }, MONACO_LOAD_TIMEOUT_MS);

    s.onload = () => finish();
    s.onerror = () => finish(new Error(`Failed to load Monaco loader: ${src}`));
    document.head.appendChild(s);
  });

  const startMonacoLoad = () => new Promise((resolve, reject) => {
    let settled = false;
    const timeoutId = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error(`Monaco modules timed out after ${MONACO_LOAD_TIMEOUT_MS} ms`));
    }, MONACO_LOAD_TIMEOUT_MS);

    const fail = (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      reject(error instanceof Error ? error : new Error(String(error || 'Monaco initialization failed')));
    };

    try {
      require.config({
        paths: { vs: MONACO_BASE_PATH },
        waitSeconds: Math.ceil(MONACO_LOAD_TIMEOUT_MS / 1000)
      });
      require(['vs/editor/editor.main'], function () {
        if (settled) return;
        try {
          const initialEditorValue = editor?.getValue?.() ?? INITIAL_EDITOR_CODE;
          monacoLoaded = true;
          fallbackTextarea.style.display = 'none';
          document.getElementById('editor-container')?.classList.add('monaco-ready');
          const isDark = document.documentElement.getAttribute('data-theme') === 'dark';

        // Define custom themes matching our Artificial Analysis variables with improved contrast
        monaco.editor.defineTheme('app-dark-theme', {
          base: 'vs-dark',
          inherit: true,
          rules: [],
          colors: {
            'editor.background': '#0b0d13',
            'editor.foreground': '#ffffff',
            'editorLineNumber.foreground': '#94a3b8',
            'editorLineNumber.activeForeground': '#8842FD',
            'editor.lineHighlightBackground': '#151821',
            'editor.selectionBackground': '#2d2542',
            'scrollbarSlider.background': '#151821',
            'scrollbarSlider.hoverBackground': '#1f2433',
            'scrollbarSlider.activeBackground': '#2d344a',
          }
        });

        monaco.editor.defineTheme('app-light-theme', {
          base: 'vs',
          inherit: true,
          rules: [],
          colors: {
            'editor.background': '#ffffff',
            'editor.foreground': '#020617',
            'editorLineNumber.foreground': '#94a3b8',
            'editorLineNumber.activeForeground': '#8842FD',
            'editor.lineHighlightBackground': '#e2e8f0',
            'editor.selectionBackground': '#f1e9ff',
            'scrollbarSlider.background': '#cbd5e1',
            'scrollbarSlider.hoverBackground': '#94a3b8',
            'scrollbarSlider.activeBackground': '#64748b',
          }
        });

        // Create the models for Monaco Editor
        unifiedModel = monaco.editor.createModel(initialEditorValue, 'html');
        unifiedModel.onDidChangeContent(() => {
          if (!isRestoringHistory) {
            handleTextChange();
          }
          if (editorMode === 'unified') {
            const entryFile = getEntryFile();
            if (entryFile) {
              markProjectPreviewDirty(entryFile.name);
            }
          }
          updateEditorPlaceholder();
          schedulePreviewUpdate({ force: false });
        });

        // Create models only for editable VFS files.
        syncModelsForFiles();

        const isMobile = window.innerWidth <= 768;
        // Create the editor instance using unifiedModel initially
        editor = monaco.editor.create(document.getElementById('editor-container'), {
          model: unifiedModel,
          theme: isDark ? 'app-dark-theme' : 'app-light-theme',
          automaticLayout: true,
          fontSize: editorFontSize,
          lineHeight: getEditorLineHeight(),
          fontFamily: "'JetBrains Mono', Consolas, monospace",
          minimap: { enabled: false },
          lineNumbers: 'on',
          lineNumbersMinChars: isMobile ? 2 : 3,
          lineDecorationsWidth: isMobile ? 8 : 24,
          glyphMargin: false,
          folding: !isMobile,
          roundedSelection: true,
          scrollBeyondLastLine: false,
          tabSize: 2,
          wordWrap: 'on',
          largeFileOptimizations: true,
          fixedOverflowWidgets: true,
          bracketPairColorization: { enabled: false },
          guides: { bracketPairs: false, indentation: false },
          occurrencesHighlight: false,
          selectionHighlight: false,
          colorDecorators: false,
          padding: { top: 16 }
        });
        initMonacoTouchScroll();

        let activeLineNumberDecorations = [];
        const syncActiveLineNumber = () => {
          const lineNumber = editor.getPosition()?.lineNumber;
          activeLineNumberDecorations = editor.deltaDecorations(
            activeLineNumberDecorations,
            lineNumber ? [{
              range: new monaco.Range(lineNumber, 1, lineNumber, 1),
              options: { lineNumberClassName: 'viewer-active-line-number' }
            }] : []
          );
        };
        editor.onDidChangeCursorPosition(syncActiveLineNumber);
        editor.onDidChangeModel(syncActiveLineNumber);
        syncActiveLineNumber();

        syncEditorZoomGutter();

        // Initial render
        updateEditorPlaceholder();
        updatePreview();
        queueEditorLayout();
        if (document.activeElement === fallbackTextarea) {
          editor.focus();
        }

        // Evento de pegado para actualizar al instante
        editor.onDidPaste(() => {
          allowPreviewFocusOnNextRender();
          schedulePreviewUpdate({ force: true });
        });

        // Monaco-specific keybindings
          editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, triggerExport);
          editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyO, triggerImport);
          editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyP, triggerPreviewFull);
          editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.Enter, triggerPreviewFull);

          settled = true;
          clearTimeout(timeoutId);
          resolve(true);
        } catch (error) {
          fail(error);
        }
      }, function (err) {
        fail(err);
      });
    } catch (e) {
      fail(e);
    }
  });

  const ensureLoader = typeof window.require === 'undefined'
    ? loadScript(MONACO_LOADER_PATH)
    : Promise.resolve();

  monacoLoadPromise = ensureLoader
    .then(startMonacoLoad)
    .catch((err) => {
      console.warn('Monaco failed to load; keeping the fallback editor available.', err);
      if (!monacoLoadFailureToastShown) {
        monacoLoadFailureToastShown = true;
        showToast(t('toast_offline_mode'), 'info');
      }
      monacoLoadPromise = null;
      return false;
    });

  return monacoLoadPromise;
}

// Start Monaco immediately after the first paint. Interaction remains a retry
// path if a deployment is incomplete or the request times out.
let monacoLoadTriggered = false;
let monacoAutomaticRetryCount = 0;
function triggerMonacoLazyLoad() {
  if (monacoLoaded || monacoLoadTriggered) return;
  monacoLoadTriggered = true;
  upgradeToMonaco().then((loaded) => {
    monacoLoadTriggered = false;
    if (loaded && editorBodyArea) {
      ['mouseenter', 'pointerdown', 'focusin'].forEach((eventName) => {
        editorBodyArea.removeEventListener(eventName, triggerMonacoLazyLoad);
      });
    } else if (!loaded && monacoAutomaticRetryCount < MONACO_MAX_AUTOMATIC_RETRIES) {
      monacoAutomaticRetryCount += 1;
      setTimeout(triggerMonacoLazyLoad, MONACO_RETRY_DELAY_MS);
    }
  });
}

const editorBodyArea = document.querySelector('.editor-body-area');
if (editorBodyArea) {
  ['mouseenter', 'pointerdown', 'focusin'].forEach((eventName) => {
    editorBodyArea.addEventListener(eventName, triggerMonacoLazyLoad);
  });
}

// Dynamic scripts do not block the current bundle or the fallback editor. Now
// that Monaco is same-origin, starting the request immediately is both the
// fastest and the most deterministic path, including in background tabs.
triggerMonacoLazyLoad();

// Update the iframe live preview content
function updatePreview() {
  if (editorMode === 'split') {
    markProjectPreviewDirty(null, { all: true });
  }
  schedulePreviewUpdate({ force: true });
}

// Keyboard Action Helpers
function triggerExport() {
  const btn = document.getElementById('btn-export');
  if (btn) btn.click();
}

function triggerImport() {
  const btn = document.getElementById('btn-import');
  if (btn) btn.click();
}

function triggerPreviewFull() {
  const btn = document.getElementById('btn-preview-full');
  if (btn) btn.click();
}

function triggerPreviewReload() {
  // Clear sessionStorage (safe for editor as it doesn't use it)
  try {
    sessionStorage.clear();
  } catch (e) {}

  // Clear localStorage keys that do not belong to editor preferences
  try {
    const EDITOR_KEYS = new Set(['theme', 'split-percent', 'explorer-width', 'cookie-consent-preferences']);
    for (let i = localStorage.length - 1; i >= 0; i--) {
      const key = localStorage.key(i);
      if (key && !EDITOR_KEYS.has(key)) {
        localStorage.removeItem(key);
      }
    }
  } catch (e) {}

  // Clear cookies set by the previewed site
  try {
    const cookies = document.cookie.split(";");
    for (let i = 0; i < cookies.length; i++) {
      const cookie = cookies[i];
      const eqPos = cookie.indexOf("=");
      const name = eqPos > -1 ? cookie.substr(0, eqPos).trim() : cookie.trim();
      document.cookie = name + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/";
    }
  } catch (e) {}

  // Clear IndexedDB databases created by previewed scripts
  try {
    if (window.indexedDB && typeof window.indexedDB.databases === 'function') {
      window.indexedDB.databases().then(dbs => {
        dbs.forEach(db => {
          if (db.name) {
            window.indexedDB.deleteDatabase(db.name);
          }
        });
      }).catch(err => {});
    }
  } catch (e) {}

  // Clear Cache Storage used by previewed scripts
  try {
    if (window.caches && typeof window.caches.keys === 'function') {
      window.caches.keys().then(keys => {
        keys.forEach(key => {
          window.caches.delete(key);
        });
      }).catch(err => {});
    }
  } catch (e) {}

  allowPreviewFocusOnNextRender();
  returnPreviewToHome();
}

function triggerFocusMode() {
  const btn = document.getElementById('btn-highlight-full');
  if (btn) btn.click();
}

// Global keyboard shortcuts
window.addEventListener('keydown', (e) => {
  const isCtrlOrCmd = e.ctrlKey || e.metaKey;
  if (isCtrlOrCmd) {
    let handled = true;
    switch (e.key.toLowerCase()) {
      case 's':
        triggerExport();
        break;
      case 'o':
        triggerImport();
        break;
      case 'p':
        triggerPreviewFull();
        break;
      default:
        handled = false;
    }

    if (e.key === 'Enter') {
      triggerPreviewFull();
      handled = true;
    }

    if (handled) {
      e.preventDefault();
      e.stopPropagation();
    }
  }
});

// Interceptar Deshacer (Ctrl+Z) y Rehacer (Ctrl+Y / Ctrl+Shift+Z) en fase de captura para anular Monaco
window.addEventListener('keydown', (e) => {
  const isCtrlOrCmd = e.ctrlKey || e.metaKey;
  if (isCtrlOrCmd) {
    const key = e.key.toLowerCase();
    if (key === 'z') {
      if (e.shiftKey) {
        triggerRedo();
      } else {
        triggerUndo();
      }
      e.preventDefault();
      e.stopPropagation();
    } else if (key === 'y') {
      triggerRedo();
      e.preventDefault();
      e.stopPropagation();
    }
  }
}, true);

function setEditorValue(value) {
  if (!editor) return;
  saveHistoryState();
  const wasRestoring = isRestoringHistory;
  isRestoringHistory = true;
  try {
    if (monacoLoaded) {
      if (editorMode === 'unified') {
        cameFromSplitMode = false;
        const rootFolder = getProjectRootFolder();
        files = [
          createTextFileRecord(rootFolder + 'index.html', value, { id: '1' })
        ];
        openFileIds = ['1'];
        selectedEntryFileId = '1';

        const model = unifiedModel;
        if (model) {
          editor.executeEdits("history-action", [{
            range: model.getFullModelRange(),
            text: value,
            forceMoveMarkers: true
          }]);
        }
      } else {
        if (value === '') {
          // Clear all files, keep index.html empty
          const rootFolder = getProjectRootFolder();
          files = [
            createTextFileRecord(rootFolder + 'index.html', '', { id: '1' })
          ];
          openFileIds = ['1'];

          disposeAllFileModels();
          normalizeProjectFiles();
          syncModelsForFiles();
          openFile('1');
        } else {
          const { html, css, js } = splitUnifiedCode(value);
          const rootFolder = getProjectRootFolder();
          files = [
            createTextFileRecord(rootFolder + 'index.html', html, { id: '1' }),
            createTextFileRecord(rootFolder + 'styles.css', css, { id: '2' }),
            createTextFileRecord(rootFolder + 'script.js', js, { id: '3' })
          ];
          openFileIds = ['1'];
          selectedEntryFileId = '1';

          disposeAllFileModels();
          normalizeProjectFiles();
          syncModelsForFiles();
          openFile('1');
        }
      }
      if (window.innerWidth > COMPACT_LAYOUT_MAX_WIDTH) {
        editor.focus();
      }
      updateEditorPlaceholder();
      updatePreview();
    } else {
      editor.setValue(value);
    }
  } finally {
    isRestoringHistory = wasRestoring;
  }
}
;

/* ---- src/app/08-layout-preview-controls.js ---- */
// Draggable split pane resizing logic
const handle = document.getElementById('resize-handle');
const overlay = document.getElementById('resize-overlay');
const editorPanel = document.getElementById('editor-panel');
const previewPanel = document.getElementById('preview-panel');
const workspace = document.getElementById('workspace-container');
let resizeLayoutFrame = 0;
const DEFAULT_EDITOR_PANEL_MIN_WIDTH = 420;
const DEFAULT_PREVIEW_PANEL_MIN_WIDTH = 420;
const MIN_SPLIT_PERCENT = 12;
const MAX_SPLIT_PERCENT = 88;

function queueEditorLayout() {
  if (!editor || resizeLayoutFrame) return;

  resizeLayoutFrame = requestAnimationFrame(() => {
    resizeLayoutFrame = 0;
    editor.layout();
    if (typeof syncEditorZoomGutter === 'function') {
      syncEditorZoomGutter();
    }
  });
}

function readLayoutPixelVar(name, fallback) {
  const sources = [workspace, document.documentElement];

  for (const source of sources) {
    if (!source) continue;
    const value = Number.parseFloat(getComputedStyle(source).getPropertyValue(name));
    if (Number.isFinite(value)) return value;
  }

  return fallback;
}

function getHorizontalMargins(element) {
  if (!element) return 0;
  const styles = getComputedStyle(element);
  const marginLeft = Number.parseFloat(styles.marginLeft) || 0;
  const marginRight = Number.parseFloat(styles.marginRight) || 0;
  return marginLeft + marginRight;
}

function getOuterInlineSize(element) {
  if (!element) return 0;
  return element.getBoundingClientRect().width + getHorizontalMargins(element);
}

function getSplitLayoutMetrics(workspaceWidth) {
  const editorMinWidth = readLayoutPixelVar('--editor-panel-min', DEFAULT_EDITOR_PANEL_MIN_WIDTH);
  const previewMinWidth = readLayoutPixelVar('--preview-panel-min', DEFAULT_PREVIEW_PANEL_MIN_WIDTH);
  const chromeWidth =
    getHorizontalMargins(editorPanel) +
    getOuterInlineSize(handle) +
    getHorizontalMargins(previewPanel);

  return {
    editorMinWidth,
    previewMinWidth,
    chromeWidth,
    availableWidth: Math.max(0, workspaceWidth - chromeWidth)
  };
}

function clampSplitPercent(percentage, workspaceWidth = workspace?.getBoundingClientRect().width || 0) {
  const fallback = Math.min(MAX_SPLIT_PERCENT, Math.max(MIN_SPLIT_PERCENT, percentage));
  if (!Number.isFinite(workspaceWidth) || workspaceWidth <= 0) return fallback;

  const { editorMinWidth, previewMinWidth, chromeWidth, availableWidth } = getSplitLayoutMetrics(workspaceWidth);
  const minByEditor = (editorMinWidth / workspaceWidth) * 100;
  const maxByPreview = ((workspaceWidth - chromeWidth - previewMinWidth) / workspaceWidth) * 100;
  const minPercent = Math.max(MIN_SPLIT_PERCENT, minByEditor);
  const maxPercent = Math.min(MAX_SPLIT_PERCENT, maxByPreview);

  if (minPercent >= maxPercent) {
    const balancedPercent = ((availableWidth * 0.5) / workspaceWidth) * 100;
    return Math.min(MAX_SPLIT_PERCENT, Math.max(MIN_SPLIT_PERCENT, balancedPercent));
  }

  return Math.min(maxPercent, Math.max(minPercent, percentage));
}

function initResizer() {
  // Load saved split position
  const savedPercent = parseFloat(localStorage.getItem('split-percent') || '55');
  // Agrupar lectura y escritura con requestAnimationFrame para evitar forced reflow en la carga inicial
  requestAnimationFrame(() => {
    const workspaceWidth = workspace?.getBoundingClientRect().width || 0;
    const initialPercent = clampSplitPercent(Number.isFinite(savedPercent) ? savedPercent : 55, workspaceWidth);
    workspace.style.setProperty('--split-percent', `${initialPercent}%`);
  });

  // Layout offsets to align handle center with cursor
  let offsetFromEditorRight = 6;
  let editorLeftMargin = 16;
  let dragWorkspaceLeft = 0;
  let dragWorkspaceWidth = 1;
  let dragHandleTop = 0;
  let dragHandleHeight = 1;

  // Helper to update the Y position of the line relative to the handle
  function updateMouseY(e) {
    const clientY = (e.touches && e.touches.length > 0) ? e.touches[0].clientY : e.clientY;
    if (clientY === undefined) return;
    if (!isResizing) {
      const handleRect = handle.getBoundingClientRect();
      dragHandleTop = handleRect.top;
      dragHandleHeight = handleRect.height;
    }
    const lineHalfHeight = 40;
    const minY = lineHalfHeight;
    const maxY = Math.max(minY, dragHandleHeight - lineHalfHeight);
    const y = Math.max(minY, Math.min(maxY, clientY - dragHandleTop));
    handle.style.setProperty('--mouse-y', `${y}px`);
  }

  // Update position on hover/movement over handle
  handle.addEventListener('mousemove', updateMouseY);
  handle.addEventListener('touchmove', updateMouseY, { passive: true });

  handle.addEventListener('mousedown', startDrag);
  handle.addEventListener('touchstart', startDrag, { passive: true });

  function startDrag(e) {
    isResizing = true;
    overlay.classList.add('active');
    handle.classList.add('active');

    // Measure layout offsets once at the start of the drag to avoid layout thrashing
    const workspaceRect = workspace.getBoundingClientRect();
    const editorRect = editorPanel.getBoundingClientRect();
    const handleRect = handle.getBoundingClientRect();

    offsetFromEditorRight = (handleRect.left + handleRect.width / 2) - editorRect.right;
    editorLeftMargin = editorRect.left - workspaceRect.left;
    dragWorkspaceLeft = workspaceRect.left;
    dragWorkspaceWidth = workspaceRect.width;
    dragHandleTop = handleRect.top;
    dragHandleHeight = handleRect.height;

    updateMouseY(e);

    document.addEventListener('mousemove', drag);
    document.addEventListener('touchmove', drag, { passive: false });
    document.addEventListener('mouseup', stopDrag);
    document.addEventListener('touchend', stopDrag);
  }

  function drag(e) {
    if (!isResizing) return;
    if (e.cancelable) e.preventDefault();

    // Support touch and mouse
    const clientX = (e.touches && e.touches.length > 0) ? e.touches[0].clientX : e.clientX;

    // Calculate target editor width to center handle on cursor
    const targetEditorWidth = clientX - dragWorkspaceLeft - editorLeftMargin - offsetFromEditorRight;
    let percentage = (targetEditorWidth / dragWorkspaceWidth) * 100;
    percentage = clampSplitPercent(percentage, dragWorkspaceWidth);

    workspace.style.setProperty('--split-percent', `${percentage}%`);

    // Also update Y position of handle line during drag
    updateMouseY(e);

    queueEditorLayout();
  }

  function stopDrag() {
    if (!isResizing) return;
    isResizing = false;
    overlay.classList.remove('active');
    handle.classList.remove('active');

    // Save position to localStorage
    const workspaceRect = workspace.getBoundingClientRect();
    const editorRect = editorPanel.getBoundingClientRect();
    const currentPercent = clampSplitPercent((editorRect.width / workspaceRect.width) * 100, workspaceRect.width);
    localStorage.setItem('split-percent', currentPercent);

    document.removeEventListener('mousemove', drag);
    document.removeEventListener('touchmove', drag);
    document.removeEventListener('mouseup', stopDrag);
    document.removeEventListener('touchend', stopDrag);
  }
}

function initExplorerResizer() {
  const explorer = document.getElementById('file-explorer');
  const resizer = document.getElementById('explorer-resizer');
  const overlay = document.getElementById('resize-overlay');

  if (!explorer || !resizer || !overlay) return;

  // Load saved explorer width
  const savedWidth = localStorage.getItem('explorer-width') || '220';
  let initialWidth = parseInt(savedWidth, 10);
  if (isNaN(initialWidth) || initialWidth < 170) {
    initialWidth = 170;
  } else if (initialWidth > 500) {
    initialWidth = 500;
  }
  explorer.style.setProperty('--explorer-width', `${initialWidth}px`);

  let startX = 0;
  let startWidth = 0;
  let isExplorerResizing = false;

  resizer.addEventListener('mousedown', startDrag);
  resizer.addEventListener('touchstart', startDrag, { passive: true });

  function startDrag(e) {
    isExplorerResizing = true;
    overlay.classList.add('active');
    resizer.classList.add('active');
    explorer.classList.add('resizing');

    startX = (e.touches && e.touches.length > 0) ? e.touches[0].clientX : e.clientX;
    const computedStyle = window.getComputedStyle(explorer);
    startWidth = parseInt(computedStyle.width, 10);

    document.addEventListener('mousemove', drag);
    document.addEventListener('touchmove', drag, { passive: false });
    document.addEventListener('mouseup', stopDrag);
    document.addEventListener('touchend', stopDrag);
  }

  function drag(e) {
    if (!isExplorerResizing) return;
    if (e.cancelable) e.preventDefault();

    const clientX = (e.touches && e.touches.length > 0) ? e.touches[0].clientX : e.clientX;
    const offset = clientX - startX;
    let newWidth = startWidth + offset;

    // Constrain width
    if (newWidth < 170) newWidth = 170;
    if (newWidth > 500) newWidth = 500;

    explorer.style.setProperty('--explorer-width', `${newWidth}px`);
    queueEditorLayout();
  }

  function stopDrag() {
    if (!isExplorerResizing) return;
    isExplorerResizing = false;

    overlay.classList.remove('active');
    resizer.classList.remove('active');
    explorer.classList.remove('resizing');

    const computedStyle = window.getComputedStyle(explorer);
    const finalWidth = parseInt(computedStyle.width, 10);
    localStorage.setItem('explorer-width', finalWidth);

    document.removeEventListener('mousemove', drag);
    document.removeEventListener('touchmove', drag);
    document.removeEventListener('mouseup', stopDrag);
    document.removeEventListener('touchend', stopDrag);

    queueEditorLayout();
  }
}

// Initialize dragging on load
initResizer();
initExplorerResizer();



// Responsive Emulator sizing controls
const controlButtons = document.querySelectorAll('.control-btn[data-size]');
const iframeWrapper = document.getElementById('iframe-wrapper');
const previewHomeBtn = document.getElementById('btn-preview-home');
const previewReloadBtn = document.getElementById('btn-preview-reload');

controlButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    controlButtons.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');

    const size = btn.getAttribute('data-size');
    iframeWrapper.className = 'iframe-wrapper'; // Reset

    if (size === '375px') {
      iframeWrapper.classList.add('restricted-mobile');
    } else if (size === '768px') {
      iframeWrapper.classList.add('restricted-tablet');
    }

    queueEditorLayout();
  });
});

if (previewHomeBtn) {
  previewHomeBtn.addEventListener('click', returnPreviewToHome);
}

if (previewReloadBtn) {
  previewReloadBtn.addEventListener('click', () => {
    previewReloadBtn.classList.remove('is-spinning');
    void previewReloadBtn.offsetWidth;
    previewReloadBtn.classList.add('is-spinning');
    triggerPreviewReload();
  });

  previewReloadBtn.addEventListener('animationend', (event) => {
    if (event.animationName === 'spin-once') {
      previewReloadBtn.classList.remove('is-spinning');
    }
  });
}

// Sidebar Navigation / Actions

// 1. Preview (Full Page)
document.getElementById('btn-preview-full').addEventListener('click', async () => {
  if (!editor) return;
  try {
    const previewWindow = window.open('', '_blank');
    if (!previewWindow) {
      showToast(t('toast_popup_blocked'), 'error');
      return;
    }

    const entryFile = getEntryFile();
    if (!entryFile) {
      previewWindow.document.open();
      previewWindow.document.write(createEmptyProjectPreviewCode());
      previewWindow.document.close();
      return;
    }

    const hasProjectPreview = await syncProjectPreviewSnapshot({ full: true });
    if (hasProjectPreview) {
      previewWindow.location.href = `${getProjectPreviewUrl(entryFile.name)}?v=${projectPreviewVersion}`;
      showToast(t('toast_project_opened_virtual'));
      return;
    }

    const { code, urlsToRevoke } = createFullPagePreviewSnapshot();
    previewWindow.document.open();
    previewWindow.document.write(code);
    previewWindow.document.close();
    setTimeout(() => {
      urlsToRevoke.forEach(url => URL.revokeObjectURL(url));
    }, 10 * 60 * 1000);
    showToast(t('toast_full_page_opened'));
  } catch (err) {
    showToast(t('toast_page_open_error'), 'error');
  }
});

// 2. Highlight (Full Page) / Focus Mode Toggle
document.getElementById('btn-highlight-full').addEventListener('click', () => {
  const appContainer = document.querySelector('.app-container');
  const btn = document.getElementById('btn-highlight-full');
  const icon = btn.querySelector('i');

  if (appContainer.classList.contains('fullscreen-editor')) {
    appContainer.classList.remove('fullscreen-editor');
    btn.classList.remove('active');
    icon.setAttribute('data-lucide', 'maximize-2');
  } else {
    appContainer.classList.add('fullscreen-editor');
    btn.classList.add('active');
    icon.setAttribute('data-lucide', 'minimize-2');
  }

  // Re-render Lucide icon
  lucide.createIcons();

  queueEditorLayout();
});

// 3. Sample
document.getElementById('btn-sample').addEventListener('click', () => {
  if (!editor) return;
  setEditorValue(DEFAULT_SAMPLE_CODE);
  showToast(t('toast_sample_loaded'));
});

// 4. Clear
document.getElementById('btn-clear').addEventListener('click', () => {
  if (!editor) return;
  setEditorValue('');
  showToast(t('toast_editor_cleared'));
});

// 5. Import from File / ZIP / Drag-and-Drop Folder
const fileInput = document.getElementById('file-input');
const assetInput = document.getElementById('asset-input');
document.getElementById('btn-import').addEventListener('click', () => {
  fileInput.click();
});

fileInput.addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file) return;

  const ext = getFileExtension(file.name);
  if (ext === 'zip') {
    await importFromZip(file);
  } else if (ext === 'html' || ext === 'htm') {
    importSingleHtmlFile(file);
  } else {
    showToast(t('toast_format_not_supported'), 'error');
  }
  fileInput.value = '';
});

if (assetInput) {
  assetInput.addEventListener('change', async (e) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length === 0) return;

    const records = [];
    for (const file of selectedFiles) {
      if (file.name.startsWith('.')) continue;
      records.push(await createRecordFromBrowserFile(file, pendingAssetTargetPath));
    }

    addFilesToProject(records, '');
    showToast(t('toast_files_added', { count: records.length }));
    pendingAssetTargetPath = '';
    assetInput.value = '';
  });
}

// 6. Export to File / Project Folder / ZIP
document.getElementById('btn-export').addEventListener('click', () => {
  if (!editor) return;
  if (editorMode === 'unified') {
    try {
      const code = getCurrentPreviewCode();
      const blob = new Blob([code], { type: 'text/html;charset=utf-8' });
      const link = document.createElement('a');

      // Get custom filename
      let filename = filenameInput ? filenameInput.value.trim() : 'index';
      if (!filename) filename = 'index';
      if (filename.toLowerCase().endsWith('.html')) {
        filename = filename.substring(0, filename.length - 5);
      }
      const fullName = `${filename}.html`;

      const downloadUrl = URL.createObjectURL(blob);
      link.href = downloadUrl;
      link.download = fullName;
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(downloadUrl), 0);
      showToast(t('toast_file_exported_as', { name: fullName }));
    } catch (err) {
      showToast(t('toast_export_error'), 'error');
    }
  } else {
    openModal('modal-export');
  }
});

// Resizing and panel alignment updates on window resize
window.addEventListener('resize', () => {
  if (editorMode === 'split' && workspace) {
    const workspaceWidth = workspace.getBoundingClientRect().width || 0;
    const currentPercent = Number.parseFloat(workspace.style.getPropertyValue('--split-percent')) || 55;
    const clamped = clampSplitPercent(currentPercent, workspaceWidth);
    workspace.style.setProperty('--split-percent', `${clamped}%`);
  }
  if (editor) {
    queueEditorLayout();
  }
  
  // Close drawer if resized beyond mobile viewport threshold
  if (window.innerWidth > COMPACT_LAYOUT_MAX_WIDTH) {
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.getElementById('sidebar-overlay');
    if (sidebar && sidebar.classList.contains('open')) {
      sidebar.classList.remove('open');
      if (overlay) overlay.classList.remove('active');
      sidebar.removeAttribute('aria-hidden');
      sidebar.inert = false;
    }
  }
});
;

/* ---- src/app/09-import-export-theme.js ---- */
// --- Modal & Project Import/Export Helpers ---
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (!modal) return;
  modal.style.display = 'flex';
  modal.offsetHeight; // Force reflow
  modal.classList.add('active');

  if (window.lucide) {
    lucide.createIcons();
  }

  // Check showDirectoryPicker compatibility for export modal
  if (modalId === 'modal-export') {
    const isSupported = typeof window.showDirectoryPicker === 'function';
    const folderOpt = document.getElementById('btn-export-folder-opt');
    const badge = document.getElementById('folder-export-compatibility');
    if (folderOpt && badge) {
      if (!isSupported) {
        folderOpt.disabled = true;
        badge.style.display = 'inline-block';
      } else {
        folderOpt.disabled = false;
        badge.style.display = 'none';
      }
    }
  }
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (!modal) return;
  modal.classList.remove('active');
  setTimeout(() => {
    if (!modal.classList.contains('active')) {
      modal.style.display = 'none';
    }
  }, 220);
}

function initModalCloseEvents() {
  const modal = document.getElementById('modal-export');
  if (!modal) return;

  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      closeModal('modal-export');
    }
  });

  const closeBtn = document.getElementById('modal-export-close');
  if (closeBtn) {
    closeBtn.addEventListener('click', () => {
      closeModal('modal-export');
    });
  }
}

function loadProjectFiles(newFiles, toastMessage = '', projectName = '') {
  if (newFiles.length === 0) return;
  saveHistoryState();
  const wasRestoring = isRestoringHistory;
  isRestoringHistory = true;
  try {
    switchEditorMode('split', false);
    disposeAllFileModels();

    let cleanProjectName = projectName ? projectName.replace(/[\\/:*?"<>|]/g, '_').trim() : '';

    // 1. Check if there is already a single top-level directory segment in all newFiles
    let commonPrefix = '';
    let isFirst = true;
    let hasCommonPrefix = true;
    for (const file of newFiles) {
      const name = file.name.replace(/\\/g, '/');
      const firstSlash = name.indexOf('/');
      if (firstSlash === -1) {
        hasCommonPrefix = false;
        break;
      }
      const prefix = name.substring(0, firstSlash + 1);
      if (isFirst) {
        commonPrefix = prefix;
        isFirst = false;
      } else if (commonPrefix !== prefix) {
        hasCommonPrefix = false;
        break;
      }
    }

    // 2. Map paths to ensure they are inside the target root folder
    if (cleanProjectName) {
      const newPrefix = cleanProjectName + '/';
      newFiles.forEach(file => {
        const name = file.name.replace(/\\/g, '/');
        if (hasCommonPrefix && name.startsWith(commonPrefix)) {
          file.name = newPrefix + name.substring(commonPrefix.length);
        } else {
          file.name = newPrefix + name;
        }
      });
    } else {
      // If no project name was specified, check if they already have a common prefix.
      // If they don't, put them under 'proyecto-importado/'.
      if (!hasCommonPrefix) {
        const newPrefix = t('imported_project_name') + '/';
        newFiles.forEach(file => {
          const name = file.name.replace(/\\/g, '/');
          file.name = newPrefix + name;
        });
      }
    }

    files = newFiles.map(normalizeFileRecord);
    normalizeProjectFiles();
    syncModelsForFiles();

    selectedEntryFileId = '';
    const entryFile = getEntryFile();
    if (entryFile && isHtmlFile(entryFile)) {
      selectedEntryFileId = entryFile.id;
    }
    collapseLargeProjectFolders(entryFile);
    if (entryFile) {
      openFileIds = [entryFile.id];
      openFile(entryFile.id);
    } else {
      openFileIds = [];
      activeFileId = '';
      if (monacoLoaded && editor) {
        editor.setModel(null);
      } else if (fallbackTextarea) {
        fallbackTextarea.value = '';
      }
      renderActiveFileSummary();
      renderFileExplorer();
      updateEditorPlaceholder();
    }
  } finally {
    isRestoringHistory = wasRestoring;
  }

  allowPreviewFocusOnNextRender();
  updatePreview();
  if (toastMessage) {
    showToast(toastMessage);
  }
}

function addFilesToProject(newFiles, targetPath = '') {
  if (newFiles.length === 0) return;
  saveHistoryState();
  const wasRestoring = isRestoringHistory;
  isRestoringHistory = true;
  try {
    if (editorMode !== 'split') {
      switchEditorMode('split', true);
    }

    newFiles.forEach(file => {
      let desiredPath;
      if (targetPath) {
        desiredPath = joinProjectPath(targetPath, getBaseName(file.name), { folder: file.isFolder });
      } else {
        const rootFolder = getProjectRootFolder();
        if (file.name.startsWith(rootFolder)) {
          desiredPath = file.name;
        } else {
          desiredPath = joinProjectPath(rootFolder, file.name, { folder: file.isFolder });
        }
      }
      file.name = getUniquePath(desiredPath, null, { folder: Boolean(file.isFolder) });
      normalizeFileRecord(file);
      files.push(file);
      if (!file.isFolder) {
        ensureParentFoldersForPath(file.name);
      }
    });

    normalizeProjectFiles();
    syncSelectedEntryFile();
    collapseLargeProjectFolders(getEntryFile());
    syncModelsForFiles();
    const firstFile = newFiles.find(file => !file.isFolder);
    if (firstFile) openFile(firstFile.id);
  } finally {
    isRestoringHistory = wasRestoring;
  }
  renderFileExplorer();
  renderActiveFileSummary();
  allowPreviewFocusOnNextRender();
  updatePreview();
}

async function compileToUnifiedHTML() {
  const entryFile = getEntryFile();
  if (!entryFile) return '';

  const dataUrlMap = await createVirtualFileDataUrlSnapshot();
  return resolveVirtualPaths(getFileText(entryFile), dataUrlMap, entryFile.name);
}

let jszipLoadingPromise = null;
function ensureJSZip() {
  if (typeof window.JSZip === 'function') {
    return Promise.resolve(window.JSZip);
  }
  if (jszipLoadingPromise) {
    return jszipLoadingPromise;
  }
  jszipLoadingPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'jszip.min.js';
    script.onload = () => {
      if (typeof window.JSZip === 'function') {
        resolve(window.JSZip);
      } else {
        reject(new Error('JSZip not defined after script load'));
      }
    };
    script.onerror = () => {
      // CDN Fallback
      const cdnScript = document.createElement('script');
      cdnScript.src = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
      cdnScript.onload = () => {
        if (typeof window.JSZip === 'function') {
          resolve(window.JSZip);
        } else {
          reject(new Error('JSZip not defined after CDN load'));
        }
      };
      cdnScript.onerror = () => reject(new Error('Failed to load JSZip from CDN'));
      document.head.appendChild(cdnScript);
    };
    document.head.appendChild(script);
  });
  return jszipLoadingPromise;
}

async function exportToZip() {
  let JSZipCtor;
  try {
    JSZipCtor = await ensureJSZip();
  } catch (err) {
    showToast(t('toast_jszip_not_loaded'), 'error');
    return;
  }

  // Get project root folder name from virtual files
  const rootFolder = getProjectRootFolder().replace(/\/$/, '');
  const folderName = rootFolder.replace(/[\\/:*?"<>|]/g, '_') || t('default_folder_name');

  const zip = new JSZipCtor();

  files.forEach(file => {
    if (file.isFolder) {
      zip.folder(file.name);
    } else {
      zip.file(file.name, getFileBlob(file));
    }
  });

  zip.generateAsync({ type: 'blob' }).then(function (content) {
    const fullName = `${folderName}.zip`;

    const downloadUrl = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = downloadUrl;
    link.download = fullName;
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(downloadUrl), 0);
    showToast(t('toast_project_exported_zip', { name: fullName }));
    closeModal('modal-export');
  }).catch(function (err) {
    showToast(t('toast_zip_generate_error'), 'error');
  });
}

async function exportToFolder() {
  if (typeof window.showDirectoryPicker !== 'function') {
    showToast(t('toast_local_export_unsupported'), 'error');
    return;
  }

  try {
    const dirHandle = await window.showDirectoryPicker({
      mode: 'readwrite'
    });

    for (const file of files) {
      if (file.isFolder) {
        const pathParts = file.name.split('/').filter(Boolean);
        let currentDirHandle = dirHandle;
        for (const part of pathParts) {
          currentDirHandle = await currentDirHandle.getDirectoryHandle(part, { create: true });
        }
        continue;
      }

      const pathParts = file.name.split('/');
      let currentDirHandle = dirHandle;

      for (let i = 0; i < pathParts.length - 1; i++) {
        const part = pathParts[i];
        if (part && part !== '.' && part !== '..') {
          currentDirHandle = await currentDirHandle.getDirectoryHandle(part, { create: true });
        }
      }

      const fileName = pathParts[pathParts.length - 1];
      const fileHandle = await currentDirHandle.getFileHandle(fileName, { create: true });
      const writable = await fileHandle.createWritable();
      await writable.write(getFileBlob(file));
      await writable.close();
    }

    showToast(t('toast_local_export_success'));
    closeModal('modal-export');
  } catch (err) {
    if (err.name === 'AbortError') {
      showToast(t('toast_export_cancelled'), 'info');
    } else {
      showToast(t('toast_folder_export_error', { message: err.message }), 'error');
    }
  }
}

async function importSingleHtmlFile(file) {
  try {
    const html = await file.text();
    if (!editor) return false;

    allowPreviewFocusOnNextRender();
    setEditorValue(html);

    let name = file.name;
    if (name.toLowerCase().endsWith('.html')) {
      name = name.substring(0, name.length - 5);
    } else if (name.toLowerCase().endsWith('.htm')) {
      name = name.substring(0, name.length - 4);
    }
    if (filenameInput) {
      filenameInput.value = name;
      adjustFilenameWidth();
    }

    showToast(t('toast_html_imported', { name: file.name }));
    return true;
  } catch (err) {
    void err;
    showToast(t('toast_html_read_error'), 'error');
    return false;
  }
}

async function importFromZip(zipFile) {
  let JSZipCtor;
  try {
    JSZipCtor = await ensureJSZip();
  } catch (err) {
    showToast(t('toast_jszip_not_loaded'), 'error');
    return false;
  }

  try {
    const zip = await JSZipCtor.loadAsync(zipFile);
    const newFiles = [];
    let fileCounter = 0;

    const promises = [];
    zip.forEach((relativePath, zipEntry) => {
      if (zipEntry.name.startsWith('__MACOSX/') || zipEntry.name.includes('/.') || zipEntry.name.startsWith('.')) {
        return;
      }

      if (zipEntry.dir) {
        newFiles.push({
          ...createFolderRecord(relativePath.endsWith('/') ? relativePath : relativePath + '/', {
            id: createFileId('folder'),
            order: nextFileOrder + fileCounter++
          })
        });
        return;
      }

      const fileId = createFileId('file');
      const order = nextFileOrder + fileCounter++;
      const promise = (isTextFilename(relativePath) ? zipEntry.async('string') : zipEntry.async('blob')).then(content => {
        const record = isTextFilename(relativePath)
          ? createTextFileRecord(relativePath, content, { id: fileId, order })
          : createBinaryFileRecord(relativePath, content, { id: fileId, order, mimeType: getMimeTypeForFilename(relativePath) });
        newFiles.push(record);
      });
      promises.push(promise);
    });

    await Promise.all(promises);

    if (newFiles.length === 0) {
      showToast(t('toast_zip_no_valid_files'), 'error');
      return false;
    }

    const zipName = zipFile.name.replace(/\.zip$/i, '');
    loadProjectFiles(newFiles, t('toast_folder_imported', { count: newFiles.length }), zipName);
    return true;
  } catch (err) {
    void err;
    showToast(t('toast_zip_import_error'), 'error');
    return false;
  }
}

async function createRecordsFromDataTransfer(dataTransfer, targetPath = '') {
  const records = [];
  const items = Array.from(dataTransfer.items || []);

  if (items.length > 0 && items.some(item => typeof item.webkitGetAsEntry === 'function')) {
    for (const item of items) {
      const entry = item.webkitGetAsEntry?.();
      if (!entry || entry.name?.startsWith('.')) continue;

      if (entry.isDirectory) {
        const entries = await readDirectoryEntryEntries(entry);
        records.push(createFolderRecord(joinProjectPath(targetPath, entry.name, { folder: true })));
        for (const nestedEntry of entries) {
          const nestedPath = joinProjectPath(joinProjectPath(targetPath, entry.name, { folder: true }), nestedEntry.relativePath, { folder: nestedEntry.isDirectory });
          if (nestedEntry.isDirectory) {
            records.push(createFolderRecord(nestedPath));
          } else {
            const browserFile = await new Promise((resolve, reject) => nestedEntry.entry.file(resolve, reject));
            const record = await createRecordFromBrowserFile(browserFile, getParentPath(nestedPath));
            record.name = normalizeProjectPath(nestedPath);
            records.push(record);
          }
        }
      } else if (entry.isFile) {
        const browserFile = item.getAsFile?.();
        if (browserFile && !browserFile.name.startsWith('.')) {
          records.push(await createRecordFromBrowserFile(browserFile, targetPath));
        }
      }
    }
    return records;
  }

  for (const file of Array.from(dataTransfer.files || [])) {
    if (file.name.startsWith('.')) continue;
    records.push(await createRecordFromBrowserFile(file, targetPath));
  }
  return records;
}

function isInternalExplorerDrag(event) {
  return internalDragState || Array.from(event.dataTransfer?.types || []).includes('application/x-vfs-item');
}

function isInternalTabDrag(event) {
  return Array.from(event.dataTransfer?.types || []).includes('application/x-editor-tab');
}

function isInternalAppDrag(event) {
  return isInternalExplorerDrag(event) || isInternalTabDrag(event);
}

function dataTransferHasFiles(event) {
  return Array.from(event.dataTransfer?.types || []).includes('Files');
}

let externalFileDragDepth = 0;
let explorerOpenedTemporarilyForDrag = false;

function getDropIntent(dataTransfer) {
  const items = Array.from(dataTransfer?.items || []).filter(item => item.kind === 'file');
  const filesToDrop = Array.from(dataTransfer?.files || []);
  const count = Math.max(items.length, filesToDrop.length);
  if (count > 1) return 'multiple';

  const item = items[0];
  const entry = item?.webkitGetAsEntry?.();
  if (entry?.isDirectory) return 'project';

  const file = filesToDrop[0] || item?.getAsFile?.();
  const ext = getFileExtension(file?.name || entry?.name || '');
  if (ext === 'zip') return 'project';
  if (ext === 'html' || ext === 'htm') return 'html';
  return 'files';
}

function showDragDropLoading(message = currentLocale === 'es' ? 'Procesando archivos...' : 'Processing files...') {
  const overlay = document.getElementById('drag-drop-overlay');
  const title = document.getElementById('drag-drop-title');
  const description = document.getElementById('drag-drop-description');
  if (!overlay || !title || !description) return;

  title.textContent = message;
  description.textContent = currentLocale === 'es' ? 'Por favor, espera un momento mientras procesamos los archivos...' : 'Please wait a moment while we process the files...';
  
  overlay.classList.add('is-processing');
  
  const icon = overlay.querySelector('.drag-drop-icon');
  if (icon) {
    icon.setAttribute('data-lucide', 'loader-2');
    icon.classList.add('animate-spin');
    if (window.lucide?.createIcons) {
      window.lucide.createIcons();
    }
  }
}

function updateDragDropOverlay(dataTransfer, { treeTarget = false } = {}) {
  const overlay = document.getElementById('drag-drop-overlay');
  const title = document.getElementById('drag-drop-title');
  const description = document.getElementById('drag-drop-description');
  const fileExplorer = document.getElementById('file-explorer');
  if (!overlay || !title || !description) return;

  // Reset overlay processing classes and icon
  overlay.classList.remove('is-processing');
  const icon = overlay.querySelector('.drag-drop-icon');
  if (icon) {
    icon.setAttribute('data-lucide', 'file-up');
    icon.classList.remove('animate-spin');
    if (window.lucide?.createIcons) {
      window.lucide.createIcons();
    }
  }

  if (treeTarget) {
    title.textContent = t('drag_title_add');
    description.textContent = t('drag_desc_add');
    overlay.classList.add('tree-target');
    overlay.classList.remove('project-target');
    fileExplorer?.classList.add('external-drop-target');
  } else {
    const intent = getDropIntent(dataTransfer);
    title.textContent = intent === 'project'
      ? t('drag_title_project')
      : (intent === 'html' ? t('drag_title_html') : t('drag_title_import'));
    description.textContent = intent === 'files'
      ? t('drag_desc_files')
      : t('drag_desc_main');
    overlay.classList.remove('tree-target');
    overlay.classList.toggle('project-target', intent === 'project');
    fileExplorer?.classList.remove('external-drop-target');
  }

  overlay.style.display = 'flex';
}

function beginExternalFileDrag(dataTransfer, target) {
  document.body.classList.add('external-file-dragging');
  if (editorMode === 'split' && isExplorerCollapsed && !explorerOpenedTemporarilyForDrag) {
    explorerOpenedTemporarilyForDrag = true;
    toggleFileExplorer(false);
  }
  updateDragDropOverlay(dataTransfer, { treeTarget: Boolean(target?.closest?.('#file-explorer')) });
}

function finishExternalFileDrag({ keepExplorerOpen = false } = {}) {
  const overlay = document.getElementById('drag-drop-overlay');
  const fileExplorer = document.getElementById('file-explorer');
  externalFileDragDepth = 0;
  document.body.classList.remove('external-file-dragging');
  overlay?.classList.remove('tree-target');
  overlay?.classList.remove('project-target');
  if (overlay) overlay.style.display = 'none';
  fileExplorer?.classList.remove('external-drop-target');
  document.getElementById('file-list')?.classList.remove('drop-inside');
  clearExplorerDropState();

  if (explorerOpenedTemporarilyForDrag && !keepExplorerOpen && !isExplorerCollapsed) {
    toggleFileExplorer(false);
  } else if (keepExplorerOpen && editorMode === 'split' && isExplorerCollapsed) {
    toggleFileExplorer(false);
  }
  explorerOpenedTemporarilyForDrag = false;
}

async function addDroppedFilesToProject(dataTransfer, targetPath = '') {
  const records = await createRecordsFromDataTransfer(dataTransfer, targetPath);
  if (records.length === 0) {
    showToast(t('toast_no_valid_import'), 'error');
    return 0;
  }
  addFilesToProject(records, '');
  return records.length;
}

async function importDroppedFilesGlobally(dataTransfer) {
  const items = Array.from(dataTransfer.items || []).filter(item => item.kind === 'file');
  const filesToDrop = Array.from(dataTransfer.files || []);
  const itemCount = Math.max(items.length, filesToDrop.length);

  if (itemCount > 1) {
    const records = await createRecordsFromDataTransfer(dataTransfer);
    if (records.length === 0) {
      showToast(t('toast_no_valid_import'), 'error');
      return { imported: false, project: false };
    }
    loadProjectFiles(records, t('toast_folder_imported', { count: records.length }), t('imported_project_name'));
    return { imported: true, project: true };
  }

  const item = items[0];
  const entry = item?.webkitGetAsEntry?.();
  if (entry?.isDirectory) {
    const imported = await importFolderEntry(entry);
    return { imported, project: imported };
  }

  const file = filesToDrop[0] || item?.getAsFile?.();
  if (!file) return { imported: false, project: false };
  const ext = getFileExtension(file.name);
  if (ext === 'zip') {
    const imported = await importFromZip(file);
    return { imported, project: imported };
  }
  if (ext === 'html' || ext === 'htm') {
    const imported = await importSingleHtmlFile(file);
    return { imported, project: false };
  }

  const added = await addDroppedFilesToProject(dataTransfer, '');
  if (added > 0) {
    const msgKey = added === 1 ? 'toast_file_added_to_project' : 'toast_files_added_to_project';
    showToast(`${added} ${t(msgKey)}`);
  }
  return { imported: added > 0, project: added > 0 };
}

// Global drop replaces/opens; file-tree handlers add through addDroppedFilesToProject().
function initDragAndDrop() {
  const container = document.querySelector('.app-container');
  const overlay = document.getElementById('drag-drop-overlay');
  if (!container || !overlay) return;

  window.addEventListener('dragenter', (event) => {
    if (!dataTransferHasFiles(event) || isInternalAppDrag(event)) return;
    event.preventDefault();
    externalFileDragDepth++;
    beginExternalFileDrag(event.dataTransfer, event.target);
  });

  window.addEventListener('dragover', (event) => {
    if (!dataTransferHasFiles(event) || isInternalAppDrag(event)) return;
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
    beginExternalFileDrag(event.dataTransfer, event.target);
  });

  window.addEventListener('dragleave', (event) => {
    if (!dataTransferHasFiles(event) || isInternalAppDrag(event)) return;
    event.preventDefault();
    if (!event.relatedTarget) {
      finishExternalFileDrag();
      return;
    }
    externalFileDragDepth = Math.max(0, externalFileDragDepth - 1);
    if (externalFileDragDepth === 0) finishExternalFileDrag();
  });

  window.addEventListener('drop', async (event) => {
    if (!dataTransferHasFiles(event)) return;
    event.preventDefault();
    if (isInternalAppDrag(event) || event.target.closest?.('#file-explorer')) return;

    showDragDropLoading(currentLocale === 'es' ? 'Importando archivos...' : 'Importing files...');
    const result = await importDroppedFilesGlobally(event.dataTransfer);
    finishExternalFileDrag({ keepExplorerOpen: result.project });
  });

  window.addEventListener('blur', () => {
    if (externalFileDragDepth > 0) finishExternalFileDrag();
  });
  document.addEventListener('dragend', () => finishExternalFileDrag());
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && externalFileDragDepth > 0) finishExternalFileDrag();
  });
}

// Recursively traverse directory entries
function readDirectoryEntryEntries(dirEntry, path = '') {
  return new Promise((resolve, reject) => {
    const dirReader = dirEntry.createReader();
    const fileEntries = [];

    const readEntries = () => {
      dirReader.readEntries(async (entries) => {
        if (entries.length === 0) {
          resolve(fileEntries);
        } else {
          for (const entry of entries) {
            if (entry.name.startsWith('.')) continue; // ignore system/hidden files

            const relativePath = path + entry.name;
            if (entry.isFile) {
              entry.relativePath = relativePath;
              fileEntries.push({ entry, relativePath, isDirectory: false });
            } else if (entry.isDirectory) {
              fileEntries.push({ entry, relativePath: `${relativePath}/`, isDirectory: true });
              try {
                const subEntries = await readDirectoryEntryEntries(entry, path + entry.name + '/');
                fileEntries.push(...subEntries);
              } catch (e) {
                void e;
              }
            }
          }
          readEntries();
        }
      }, reject);
    };
    readEntries();
  });
}

async function importFolderEntry(directoryEntry) {
  try {
    const fileEntries = await readDirectoryEntryEntries(directoryEntry);
    const newFiles = [];

    for (let i = 0; i < fileEntries.length; i++) {
      const fileEntry = fileEntries[i];
      if (fileEntry.isDirectory) {
        newFiles.push(createFolderRecord(fileEntry.relativePath));
        continue;
      }

      const browserFile = await new Promise((resolve, reject) => {
        fileEntry.entry.file(resolve, reject);
      });
      const record = await createRecordFromBrowserFile(browserFile, getParentPath(fileEntry.relativePath));
      record.name = normalizeProjectPath(fileEntry.relativePath);
      newFiles.push(record);
    }

    if (newFiles.length === 0) {
      showToast(t('toast_no_valid_import'), 'error');
      return false;
    }

    const folderName = directoryEntry.name;
    loadProjectFiles(newFiles, t('toast_folder_imported', { count: newFiles.length }), folderName);
    return true;
  } catch (err) {
    void err;
    showToast(t('toast_folder_import_error'), 'error');
    return false;
  }
}

function initImportExportOptions() {
  initModalCloseEvents();

  // --- EXPORT MODAL BINDINGS ---
  const btnExportFolderOpt = document.getElementById('btn-export-folder-opt');
  if (btnExportFolderOpt) {
    btnExportFolderOpt.addEventListener('click', () => {
      exportToFolder();
    });
  }

  const btnExportZipOpt = document.getElementById('btn-export-zip-opt');
  if (btnExportZipOpt) {
    btnExportZipOpt.addEventListener('click', () => {
      exportToZip();
    });
  }

  const btnExportUnifiedOpt = document.getElementById('btn-export-unified-opt');
  if (btnExportUnifiedOpt) {
    btnExportUnifiedOpt.addEventListener('click', async () => {
      if (!editor) return;
      try {
        const code = await compileToUnifiedHTML();
        const blob = new Blob([code], { type: 'text/html;charset=utf-8' });
        const link = document.createElement('a');

        let filename = filenameInput ? filenameInput.value.trim() : 'index';
        if (!filename) filename = 'index';
        if (filename.toLowerCase().endsWith('.html')) {
          filename = filename.substring(0, filename.length - 5);
        }
        const suffix = currentLocale === 'es' ? '_unificado.html' : '_unified.html';
        const fullName = `${filename}${suffix}`;

        const downloadUrl = URL.createObjectURL(blob);
        link.href = downloadUrl;
        link.download = fullName;
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(downloadUrl), 0);
        showToast(t('toast_unified_html_exported', { name: fullName }));
        closeModal('modal-export');
      } catch (err) {
        showToast(t('toast_unified_export_error'), 'error');
      }
    });
  }
}


// Theme Toggle (Dark / Light)
document.getElementById('btn-theme').addEventListener('click', () => {
  const htmlEl = document.documentElement;
  const currentTheme = htmlEl.getAttribute('data-theme');
  const newTheme = currentTheme === 'dark' ? 'light' : 'dark';

  htmlEl.setAttribute('data-theme', newTheme);
  localStorage.setItem('theme', newTheme);

  // Update UI Text
  const themeLabel = document.querySelector('#btn-theme span');

  if (newTheme === 'dark') {
    themeLabel.textContent = t('sidebar_mode_dark');
    if (editor && monacoLoaded) {
      monaco.editor.setTheme('app-dark-theme');
    }
  } else {
    themeLabel.textContent = t('sidebar_mode_light');
    if (editor && monacoLoaded) {
      monaco.editor.setTheme('app-light-theme');
    }
  }

  if (previewIframe?.classList.contains('is-empty')) {
    lastPreviewCode = '';
    schedulePreviewUpdate({ force: true });
  }
});
